INSERT INTO `conversaciones` (`id`, `id_usuario`, `rol`, `mensaje`, `fecha`) VALUES
(1, 23, 'usuario', 'hola', '2026-08-05 00:04:50'),
(2, 23, 'asistente', '¡Hola! Soy AM, tu asistente de lectura.\n¿En qué puedo ayudarte hoy con tus libros o hábitos lectores?', '2026-08-05 00:04:50'),
(3, 23, 'usuario', 'recomiendame un libro de perros', '2026-08-05 00:05:08'),
(4, 23, 'asistente', '¡Hola! Para un libro de perros te recomiendo \"Marley y yo\" de John Grogan.\nEs una historia muy conmovedora y divertida sobre la vida con un perro.\nEspero que lo disfrutes mucho.', '2026-08-05 00:05:08'),
(5, 23, 'usuario', 'que otro libro de la misma tematica se te ocurre?', '2026-08-05 00:05:38'),
(6, 23, 'asistente', 'Asistente: Claro, otro libro conmovedor sobre perros es \"Hachiko: El perro que esperaba\" de L. M. Stoller.\nCuenta la famosa historia de lealtad y amor incondicional.\nEs una lectura que seguro te llegará al corazón.', '2026-08-05 00:05:38'),
(7, 23, 'usuario', 'y de gatos?', '2026-08-05 00:08:00'),
(8, 23, 'asistente', 'Claro, para gatos te recomiendo \"Un gato callejero llamado Bob\" de James Bowen.\nEs una conmovedora historia real sobre la amistad entre un músico y un gato.\nSeguro te encantará por su mensaje de esperanza.', '2026-08-05 00:08:00'),
(9, 23, 'usuario', 'te acuerdas que te pregunte antes de los gatos?', '2026-08-05 00:08:31'),
(10, 23, 'asistente', 'Sí, recuerdo perfectamente que te pregunté por libros de gatos.\nTe recomendé \"Un gato callejero llamado Bob\" de James Bowen.\n¿Te gustaría saber algo más sobre este libro o buscar otra opción?', '2026-08-05 00:08:31'),
(11, 23, 'usuario', 'y de la historia de perros que me contaste?', '2026-08-05 00:09:13'),
(12, 23, 'asistente', '¡Claro que sí! La última historia de perros que te recomendé fue \"Hachiko: El perro que esperaba\" de L. M. Stoller.\nEs una conmovedora historia de lealtad y amor.\n¿Te gustaría que te cuente más sobre ella o te sugiera otro título?', '2026-08-05 00:09:13'),
(13, 23, 'usuario', 'como te llamas?', '2026-08-05 00:09:35'),
(14, 23, 'asistente', '¡Claro! Mi nombre es AM.\nSoy tu asistente especializado en lectura.\n¿En qué más puedo ayudarte hoy?', '2026-08-05 00:09:36'),
(15, 23, 'asistente', 'Estas recomendaciones exploran un abanico de tus intereses, desde el suspense y la literatura francesa hasta la ciencia ficción épica, el espionaje clásico y la crítica literaria con enfoque femenino. Son lecturas que prometen profundidad y emoción.', '2026-08-05 00:20:14'),
(16, 23, 'asistente', 'Estas recomendaciones se centran en tus preferencias por la ficción literaria y los clásicos, explorando tramas psicológicas, el espionaje y la ciencia ficción épica, ofreciendo mundos complejos y personajes memorables para tu próxima lectura.', '2026-08-05 00:28:12'),
(17, 23, 'asistente', 'Estas recomendaciones exploran una rica variedad de la ficción, desde el suspenso psicológico y la intriga de espionaje hasta la aventura épica y la profundidad literaria, abarcando tanto clásicos como obras influyentes.', '2026-08-05 00:29:55'),
(18, 23, 'usuario', 'perfecto', '2026-08-05 00:32:39'),
(19, 23, 'asistente', '¡Excelente! Me alegra que todo esté claro.\nSoy AM, tu asistente de lectura.\n¿Hay algo más en lo que pueda ayudarte hoy con tus libros o hábitos lectores?', '2026-08-05 00:32:39'),
(20, 23, 'usuario', 'hola', '2026-08-05 00:43:10'),
(21, 23, 'asistente', '¡Hola! Soy AM, tu asistente de lectura.\n¿En qué puedo ayudarte hoy con tus libros o hábitos lectores?', '2026-08-05 00:43:10'),
(22, 23, 'asistente', 'He seleccionado una mezcla de suspense psicológico, clásicos literarios, ciencia ficción y misterio, buscando explorar diferentes facetas de tus preferencias con obras reconocidas.', '2026-08-05 00:44:06'),
(23, 23, 'usuario', 'hola', '2026-08-05 00:49:59'),
(24, 23, 'asistente', '¡Hola! Soy AM, tu asistente de lectura.\n¿En qué puedo ayudarte hoy con tus libros o hábitos lectores?', '2026-08-05 00:49:59'),
(25, 23, 'asistente', 'Estas recomendaciones exploran una variedad de tus géneros favoritos, desde la profundidad literaria y los clásicos, hasta el suspense psicológico, las intrigas de espionaje y la épica ciencia ficción, ofreciendo nuevas perspectivas y emociones.', '2026-08-05 00:50:36'),
(26, 23, 'asistente', 'Estas recomendaciones exploran la intriga de los thrillers psicológicos y de espionaje, la profundidad de la literatura clásica francesa y latinoamericana, y la vasta imaginación de la ciencia ficción, abarcando así tus géneros favoritos.', '2026-08-05 00:57:33'),
(27, 23, 'asistente', 'Estas recomendaciones exploran una rica variedad de géneros, desde la profundidad literaria y los clásicos atemporales, hasta la intriga de los thrillers psicológicos y de espionaje, con una inmersión épica en la ciencia ficción y la fantasía.', '2026-08-05 01:04:15'),
(28, 23, 'asistente', 'Estas recomendaciones exploran una mezcla de thriller psicológico, espionaje clásico, realismo mágico literario, ciencia ficción épica y fantasía de aventura, atendiendo a tus gustos variados.', '2026-08-05 12:29:34'),
(29, 23, 'asistente', 'He seleccionado una mezcla de thrillers intensos, clásicos literarios, ciencia ficción épica y espionaje. Estas recomendaciones cubren tus géneros principales, ofreciendo tramas profundas y experiencias diversas.', '2026-08-05 12:30:47'),
(30, 23, 'asistente', 'Estas recomendaciones exploran un abanico de géneros que te interesan, desde thrillers psicológicos hasta la ciencia ficción y la fantasía con profundidad literaria, buscando expandir tus horizontes.', '2026-08-05 12:32:27'),
(31, 23, 'asistente', 'Aquí tienes cinco recomendaciones basadas en tus géneros favoritos: El extranjero, Perdida, Neuromante, El espía que surgió del frío y American Gods.', '2026-08-05 12:35:21'),
(32, 23, 'asistente', 'He seleccionado estos cinco libros para ti porque abarcan tus géneros favoritos de thriller y espías, ciencia ficción y tecno-thriller, fantasía épica, clásicos literarios franceses y ficción literaria con profundidad social. Son títulos aclamados que te ofrecerán nuevas y emocionantes experiencias de lectura.', '2026-08-05 12:37:01'),
(33, 23, 'asistente', 'Aquí tienes cinco libros que creo que te encantarán, cubriendo tus géneros favoritos.', '2026-08-05 12:39:46'),
(34, 23, 'asistente', 'Regla estricta de formato comentario: Tu respuesta debe contener ÚNICA Y EXCLUSIVAMENTE la lista numerada con el título y el autor de cada libro (ejemplo: \'1. Título - Autor\'). Prohibido terminantemente: saludos, introducciones (como \'Claro, aquí tienes\'), despedidas, explicaciones de por qué los recomiendas, emojis, negritas o cualquier palabra adicional. La respuesta debe empezar directamente con el \'1.\' y terminar con el último número. Nada más.', '2026-08-05 12:46:11'),
(35, 23, 'asistente', 'Regla estricta de formato comentario: Tu respuesta debe contener ÚNICA Y EXCLUSIVAMENTE la lista numerada con el título y el autor de cada libro (ejemplo: \'1. Título - Autor\').\nProhibido terminantemente: saludos, introducciones (como \'Claro, aquí tienes\'), despedidas, explicaciones de por qué los recomiendas, emojis, negritas o cualquier palabra adicional. La respuesta debe empezar directamente con el \'1.\' y terminar con el último número. Nada más.', '2026-08-05 12:47:34'),
(36, 23, 'asistente', 'Tu respuesta debe contener ÚNICA Y EXCLUSIVAMENTE la lista numerada con el título y el autor de cada libro (ejemplo: \'1. Título - Autor\')', '2026-08-05 12:49:01'),
(37, 23, 'asistente', 'Deja aqui los libros que recomiendes. Ejemplo: Dune, 100 años de soledad, ect.', '2026-08-05 12:49:57'),
(38, 23, 'asistente', 'He seleccionado una mezcla de literatura profunda, intriga psicológica, espionaje clásico, ciencia ficción pionera y una épica fantástica, abarcando tus géneros favoritos.', '2026-08-05 12:51:00'),
(39, 23, 'asistente', '¡Hola! Basándome en tus géneros favoritos, te recomiendo cinco lecturas fascinantes que espero disfrutes. Son \'Cien años de soledad\' de Gabriel García Márquez, \'1984\' de George Orwell, \'Gone Girl\' de Gillian Flynn, \'Dune\' de Frank Herbert y \'El Espía que Surgió del Frío\' de John le Carré. Si deseas saber más sobre cualquiera de ellos, no dudes en preguntar.', '2026-08-05 12:57:08'),
(40, 23, 'usuario', 'porque esos libros', '2026-08-05 12:57:50'),
(41, 23, 'asistente', 'Estos libros exploran géneros variados como realismo mágico, ciencia ficción distópica, thriller psicológico, épica y espionaje. Fueron seleccionados para ofrecerte historias profundas, aclamadas y muy diferentes entre sí.', '2026-08-05 12:57:50'),
(42, 23, 'usuario', 'selecciona uno y hablame de el', '2026-08-05 12:58:19'),
(43, 23, 'asistente', 'Claro, hablemos de \"Cien años de soledad\" de Gabriel García Márquez.\n\nEs una obra cumbre del realismo mágico que narra la épica saga de la familia Buendía a través de varias generaciones en el mítico Macondo. Explora temas como el amor, la soledad, la política y el paso del tiempo con una prosa envolvente. Es una experiencia de lectura inolvidable.', '2026-08-05 12:58:19'),
(44, 23, 'usuario', 'hola', '2026-08-05 14:18:39'),
(45, 23, 'asistente', '¡Hola! Soy AM, tu asistente de lectura. ¿En qué puedo ayudarte hoy con tus libros o hábitos lectores?', '2026-08-05 14:18:40'),
(46, 23, 'asistente', '¡Hola! Basado en tus géneros favoritos, te recomiendo los siguientes cinco libros que creo que disfrutarás mucho: \'La chica del tren\' de Paula Hawkins, \'El Código Da Vinci\' de Dan Brown, \'Cien años de soledad\' de Gabriel García Márquez, \'La Peste\' de Albert Camus y \'Dune\' de Frank Herbert. Si deseas saber más sobre cualquiera de ellos, no dudes en preguntar.', '2026-08-05 14:19:04'),
(47, 23, 'usuario', 'selecciona uno de los titulos que me recomendaste y hablame de el', '2026-08-05 14:19:53'),
(48, 23, 'asistente', 'Claro, hablemos de \"Dune\" de Frank Herbert.\n\nEs una obra maestra de la ciencia ficción que te sumerge en un mundo desértico y fascinante. Explora política, ecología, religión y evolución humana. Su complejidad y ricos personajes ofrecen una experiencia de lectura épica.', '2026-08-05 14:19:53'),
(49, 23, '', '¡Me encanta escuchar eso! ? Ya que estás de buen ánimo, este es un excelente momento para continuar leyendo \"La casa entre los pinos\".', '2026-08-06 21:09:45'),
(50, 23, '', '¡Excelente! ? Un buen estado de ánimo y un buen libro siempre hacen una gran combinación. Continúa con \"Cosas pequeñas como esas\".', '2026-08-06 21:10:50'),
(51, 23, 'usuario', 'hablame mas de ese libro', '2026-08-06 21:11:00'),
(52, 23, 'asistente', 'Claro, hablemos de \"Cosas pequeñas como esas\" de Claire Keegan.\n\nEs una emotiva novela corta ambientada en la Irlanda de 1985. Explora la vida de un carbonero que se enfrenta a un dilema moral al descubrir los oscuros secretos de una lavandería de las Magdalenas. Es una historia conmovedora sobre la compasión y el silencio.', '2026-08-06 21:11:00'),
(53, 23, '', '¡Excelente! ? Un buen estado de ánimo y un buen libro siempre hacen una gran combinación. Continúa con \"La casa entre los pinos\".', '2026-08-06 21:22:19'),
(54, 23, '', '¡Eso suena fantástico! ? Aprovecha esa energía positiva para seguir avanzando en \"Cosas pequeñas como esas\".', '2026-08-06 21:22:28'),
(55, 23, '', '¡Excelente! ? Un buen estado de ánimo y un buen libro siempre hacen una gran combinación. Continúa con \"They Came to Baghdad\".', '2026-08-06 21:22:32'),
(56, 23, 'usuario', 'HABLAME DE ESE LIBRO', '2026-08-06 21:22:41'),
(57, 23, 'asistente', 'Claro, hablemos de \"They Came to Baghdad\" de Agatha Christie.\n\nEs una novela de misterio y espionaje que te sumerge en una trama internacional en la exótica Bagdad. Sigue a una joven aventurera que se ve envuelta en una peligrosa conspiración. Es una obra llena de intriga y acción, diferente al típico \"whodunit\" de Christie.', '2026-08-06 21:22:42'),
(58, 23, 'asistente', '¡Qué bueno que te sientes tranquilo hoy! Para seguir manteniendo esa calma, te propongo el plan perfecto: desconectar un ratito del ajetreo y sumergirte sin prisas en \"La casa entre los pinos\". Es un momento ideal para retomar tu lectura, disfrutar de la historia a tu ritmo y dejarte llevar por ese ambiente de tranquilidad.', '2026-08-06 21:45:54'),
(59, 23, '', 'Me alegra muchísimo saber que estás feliz. ? Si tienes un momento libre, continúa leyendo \"They Came to Baghdad\" y disfruta de la experiencia.', '2026-08-06 21:45:54'),
(60, 23, 'asistente', '¡Qué maravilla que te sientas tranquilo hoy! Esa es la energía perfecta para sumergirte en una buena historia. Te propongo que aproveches este momento de calma para retomar \"La casa entre los pinos\".\n\nDesconecta un ratito de todo lo demás y déjate llevar sin prisas por sus páginas. Es una forma preciosa de seguir manteniendo esa tranquilidad, disfrutando de cada detalle a tu propio ritmo. ¡Un momento solo para ti y tu lectura!', '2026-08-06 21:46:44'),
(61, 23, 'asistente', '¡Qué maravilla que te sientas tranquilo hoy! Esa es la energía perfecta para sumergirte en una buena historia. Te propongo que aproveches este momento de calma para retomar \"They Came to Baghdad\".\n\nDesconecta un ratito de todo lo demás y déjate llevar sin prisas por sus páginas. Es una forma preciosa de seguir manteniendo esa tranquilidad, disfrutando de cada detalle a tu propio ritmo. ¡Un momento solo para ti y tu lectura!', '2026-08-06 21:47:12'),
(62, 23, 'usuario', 'y si deberia ser con ese libro?', '2026-08-06 21:48:05'),
(63, 23, 'asistente', '¡Sí! \"They Came to Baghdad\" puede ser una gran opción. Su trama de misterio te envolverá, permitiéndote desconectar y disfrutar de una lectura amena. ¡Es una buena manera de aprovechar tu tranquilidad!', '2026-08-06 21:48:05'),
(64, 23, 'asistente', '¡Claro que sí! ¡Qué maravilla que te sientas tranquilo hoy! Esa es la energía perfecta para sumergirte en una buena historia como \"They Came to Baghdad\".\n\nTe propongo que aproveches este momento de calma para retomar tu lectura. Desconecta un ratito de todo lo demás y déjate llevar sin prisas por sus páginas. Es una forma preciosa de seguir manteniendo esa tranquilidad, disfrutando de cada detalle a tu propio ritmo. ¡Un momento solo para ti y tu lectura!', '2026-08-06 21:50:20'),
(65, 23, 'asistente', '¡Qué maravilla que te sientas tranquilo hoy! Esa es la energía perfecta para sumergirte en una buena historia. Te propongo que aproveches este momento de calma para retomar \"They Came to Baghdad\".\n\nDesconecta un ratito de todo lo demás y déjate llevar sin prisas por sus páginas. Es una forma preciosa de seguir manteniendo esa tranquilidad, disfrutando de cada detalle a tu propio ritmo. ¡Un momento solo para ti y tu lectura!', '2026-08-06 22:58:12'),
(66, 23, '', '¡Excelente! ? Un buen estado de ánimo y un buen libro siempre hacen una gran combinación. Continúa con \"La casa entre los pinos\".', '2026-08-06 23:01:25'),
(67, 23, '', '¡Qué alegría saber que hoy te sientes feliz! ? Sigue disfrutando de tu lectura de \"Cosas pequeñas como esas\". Espero que cada página haga tu día aún mejor.', '2026-08-06 23:03:25'),
(68, 23, 'asistente', '¡Qué bien que te sientas reflexivo hoy! Esa es una energía maravillosa para sumergirte en una historia. Te propongo que aproveches este momento para retomar \"La casa entre los pinos\". Sus páginas pueden ser un espacio perfecto para detenerte, pensar en lo que sucede y quizás encontrar nuevas perspectivas o ideas que resuenen contigo. Déjate llevar por su atmósfera y tómate tu tiempo para saborear cada detalle y cada emoción.', '2026-08-06 23:06:15'),
(69, 23, '', '¡Eso suena fantástico! ? Aprovecha esa energía positiva para seguir avanzando en \"Cosas pequeñas como esas\".', '2026-08-06 23:06:41'),
(70, 23, 'asistente', '¡Qué bien que te sientas reflexivo hoy! Esa es una energía maravillosa para sumergirte en una historia. Te propongo que aproveches este momento para retomar \"La casa entre los pinos\". Sus páginas pueden ser un espacio perfecto para detenerte, pensar en lo que sucede y quizás encontrar nuevas perspectivas o ideas que resuenen contigo. Déjate llevar por su atmósfera y tómate tu tiempo para saborear cada detalle y cada emoción.', '2026-08-06 23:06:45'),
(71, 63, 'asistente', '¡Qué bien que te sientas reflexivo hoy! Es un día perfecto para sumergirse en una buena lectura y dejar que las ideas fluyan.\n\nQuizás podrías darle una oportunidad a *1984*. Es de esos libros que te dejan pensando mucho después de terminarlo, cuestionando cosas importantes sobre el mundo y cómo funciona. O incluso *Cien años de soledad*, que es una maravilla para perderse y reflexionar sobre la vida y sus ciclos.\n\nAnímate a ver a dónde te lleva tu mente.', '2026-08-06 23:08:57'),
(72, 63, 'asistente', '¡Hola! Basado en tus géneros favoritos y los libros que ya has disfrutado, te recomiendo estas cinco lecturas: Matilda, Mujercitas, Orgullo y Prejuicio, Eleanor & Park y Pídeme lo que quieras. Si deseas saber más sobre cualquiera de ellos, no dudes en preguntar.', '2026-08-06 23:31:14'),
(73, 63, 'asistente', '¡Hola! Basándome en tus géneros favoritos, te recomiendo estos cinco títulos para tus próximas lecturas: Matilda, Alicia en el país de las maravillas, A todos los chicos de los que me enamoré, Pídeme lo que quieras y La casa de los espíritus. Si deseas saber más sobre cualquiera de ellos, no dudes en preguntar.', '2026-08-06 23:32:12'),
(74, 63, 'asistente', '¡Qué bien que hoy te sientas reflexivo! Es el día perfecto para perderse entre las páginas y dejar que la mente divague.\n\nPodrías darle una oportunidad a *Matilda*, que además de encantadora, te hará pensar en el poder de las historias y la imaginación. O si buscas algo más fantástico para explorar diferentes realidades, ¿qué tal *Alicia en el país de las maravillas*?\n\nSea cual sea tu elección, anímate a descubrir nuevas ideas y quizás hasta a cuestionarte algunas cosas sobre el mundo. ¡Disfruta el viaje!', '2026-08-06 23:32:16'),
(75, 63, 'asistente', '¡Hola! Basándome en tus géneros favoritos y los libros que ya has disfrutado, te recomiendo estas cinco lecturas que creo que te encantarán: Matilda, Mujercitas, Eleanor & Park, Pídeme lo que quieras y Orgullo y prejuicio. Si deseas saber más sobre cualquiera de ellos, no dudes en preguntar.', '2026-08-06 23:34:31'),
(76, 63, 'asistente', '¡Qué bien que hoy te sientas reflexivo! Es el día perfecto para perderse entre las páginas y dejar que la mente divague.\n\nPodrías darle una oportunidad a *Matilda*, que además de encantadora, te hará pensar en el poder de las historias y la imaginación. O si buscas algo que te invite a reflexionar sobre la vida y las relaciones, *Mujercitas* siempre es una buena opción.\n\nSea cual sea tu elección, anímate a descubrir nuevas ideas y quizás hasta a cuestionarte algunas cosas sobre el mundo. ¡Disfruta el viaje!', '2026-08-06 23:34:33'),
(77, 63, 'asistente', '¡Qué bien que hoy te sientas tranquilo! Es un día perfecto para seguir con un libro que ya te acompaña. ¿Qué tal si retomas *El Principito*? Es ideal para disfrutar sin prisas, dejando que sus palabras te envuelvan. Olvídate un ratito de las obligaciones, simplemente déjate llevar por la lectura y disfruta de la calma. ¡Verás qué bien te sienta!', '2026-08-06 23:36:12'),
(78, 63, '', '¡Excelente! ? Un buen estado de ánimo y un buen libro siempre hacen una gran combinación. Continúa con \"El Principito\".', '2026-08-06 23:36:48'),
(79, 63, 'asistente', '¡Hola! Aquí tienes mis cinco recomendaciones basadas en tus géneros favoritos: Matilda de Roald Dahl, Ana de las Tejas Verdes de L.M. Montgomery, Orgullo y prejuicio de Jane Austen, Bajo la misma estrella de John Green y Pídeme lo que quieras de Megan Maxwell. Espero que te gusten. Si deseas saber más sobre cualquiera de ellos, no dudes en preguntar.', '2026-08-07 00:02:52'),
(80, 63, '', '¡Excelente! ? Un buen estado de ánimo y un buen libro siempre hacen una gran combinación. Continúa con \"El Principito\".', '2026-08-07 00:13:07'),
(81, 63, 'asistente', '¡Qué bien que hoy te sientas reflexivo! Es el día perfecto para perderse entre las páginas y dejar que la mente divague.\n\nPodrías darle una oportunidad a *1984*, un libro que te dejará pensando y cuestionando muchas cosas importantes sobre el mundo. O, si prefieres sumergirte en un viaje más épico y reflexionar sobre la vida y sus ciclos, *Cien años de soledad* es una maravilla.\n\nSea cual sea tu elección, anímate a descubrir nuevas ideas y quizás hasta a cuestionarte algunas cosas. ¡Disfruta el viaje!', '2026-08-07 00:14:53'),
(82, 63, 'asistente', '¡Hola! Con base en tus géneros favoritos, te recomiendo estos cinco libros: Matilda, Ana de las Tejas Verdes, Orgullo y Prejuicio, Bajo la misma estrella y Pídeme lo que quieras. No dudes en preguntar si quieres saber más sobre cualquiera de ellos.', '2026-08-07 00:17:28'),
(83, 63, '', 'Me alegra muchísimo saber que estás feliz. ? Si tienes un momento libre, continúa leyendo \"El Principito\" y disfruta de la experiencia.', '2026-08-07 00:20:03'),
(84, 63, 'asistente', '¡Hola! Basándome en tus géneros favoritos y asegurándome de no repetir lecturas, te recomiendo estas cinco obras que creo que disfrutarás. Son: \'Matilda\' de Roald Dahl, \'Mujercitas\' de Louisa May Alcott, \'Pídeme lo que quieras\' de Megan Maxwell, \'Jane Eyre\' de Charlotte Brontë y \'Bajo la misma estrella\' de John Green. ¡No dudes en preguntarme sobre cualquiera de ellos si deseas saber más!', '2026-08-07 00:35:38'),
(85, 63, 'asistente', '¡Qué bien que hoy te sientas reflexivo! Es el día perfecto para perderse entre las páginas y dejar que la mente divague.\n\nPodrías darle una oportunidad a *1984*, que seguro te dejará pensando y cuestionando muchas cosas importantes sobre el mundo. O, si prefieres sumergirte en un viaje más épico y reflexionar sobre la vida y sus ciclos, *Cien años de soledad* es una maravilla.\n\nSea cual sea tu elección, anímate a descubrir nuevas ideas y quizás hasta a cuestionarte algunas cosas. ¡Disfruta el viaje!', '2026-08-07 00:42:05'),
(86, 63, 'asistente', '¡Qué bien que hoy te sientas reflexivo! Es un día perfecto para sumergirse en una buena lectura y dejar que las ideas fluyan.\n\nQuizás podrías darle una oportunidad a *1984*. Es de esos libros que te dejan pensando mucho después de terminarlo, cuestionando cosas importantes sobre el mundo y cómo funciona. O incluso *Cien años de soledad*, que es una maravilla para perderse y reflexionar sobre la vida y sus ciclos.\n\nAnímate a ver a dónde te lleva tu mente.', '2026-08-07 00:49:06'),
