INSERT INTO `libros` (`id_libro`, `titulo`, `autor`, `descripcion`, `formato`, `genero`, `es_agregado_manualmente`, `num_caps`, `id_usuario`, `portada`, `categoria`, `key_libro`, `paginas_totales`, `id_google`, `anio`) VALUES
(41, 'Dino IQ (Smart Kids)', 'Roger Priddy', 'Descripción no disponible', 'Libro Físico', NULL, NULL, 10, 22, 'https://covers.openlibrary.org/b/id/1170398-L.jpg', 'leyendo', '/works/OL3260124W', 45, NULL, NULL),
(43, 'The lord of the rings', 'Jude Fisher', 'Descripción no disponible', 'Libro Físico', NULL, NULL, 12, 22, 'https://covers.openlibrary.org/b/id/393983-L.jpg', 'leyendo', '/works/OL5753836W', 65, NULL, NULL),
(44, 'Dinosaur Babies', 'Leonie Bennett', 'Did dinosaurs lay eggs in nests? How big were the eggs? What were the shells like? Did mother dinosaurs care for their babies? These and other questions about the birth and care of dinosaur babies are answered in this fascinating peek into the home lives of these reptiles. The simple text and exciting illustrations along with the tantalizing information will capture the interest of all young readers. Developed by literacy experts, Dinosaur Babies features controlled text with appropriate vocabulary, grammar, and sentence structure for emergent readers. Dinosaur Babies is part of Bearport\'s I Love Reading: Dino World series.', 'Libro Físico', NULL, NULL, 7, 6, 'https://covers.openlibrary.org/b/id/1998640-L.jpg', 'leyendo', '/works/OL5837360W', 244, NULL, NULL),
(45, 'Aiki ne waza', 'Autor desconocido', 'Descripción no disponible', NULL, NULL, NULL, NULL, 6, 'https://covers.openlibrary.org/b/id/13585127-L.jpg', 'pendiente', '/works/OL34818907W', 192, NULL, NULL),
(46, 'Hermano Lobo', 'Autor desconocido', 'Descripción no disponible', 'Libro Físico', NULL, NULL, 25, 6, 'https://covers.openlibrary.org/b/id/14474590-L.jpg', 'leyendo', '/works/OL25379493W', 224, NULL, NULL),
(64, 'Official Roster of the Soldiers of the State of Ohio in the War of the Rebellion, 1861-1866', 'Ohio. Roster Commission', 'Descripción no disponible', NULL, NULL, NULL, NULL, 6, 'https://books.google.com/books/content?id=mHxIAQAAMAAJ&printsec=frontcover&img=1&zoom=1&edge=curl&imgtk=AFLRE73JjK6M_kY6Nk_LFplwbVWEj359jcnVt5bPAp2i8LLDHEuQ0vlQuvY5CotohueE9c6KnTTIjRuyUk0AZW22ruXy_Wgz965tv3OboFazmu-9HngF8HPFiDy54NCgA6pzHnqSe-qw&source=gbs_api', 'leyendo', '', 800, 'mHxIAQAAMAAJ', '1886'),
(68, 'Dos putas en una moto', 'PEDRO', '', NULL, 'misterio', 1, NULL, 6, '/static/uploads/db9699d1d5aebb7264c0568bb9fda1f4.jpg', 'pendiente', NULL, 321, NULL, '1456'),
(69, 'Dos putas en una moto2', 'waza', '', NULL, 'misterio', 1, NULL, 6, '/static/uploads/1786b2947d0846c3b6f9f006e719f727tplv-jj85edgx6n-image-origin.jpeg', 'pendiente', NULL, 12, NULL, '1234'),
(71, 'Dinosaurs', 'Dougal Dixon, David Lambert', 'It\'s a weird world out there... dazzle your friends with wacky facts and more from this mega new series. Did you know... A charging Triceratops could gore an enemy to death with its three terrifying horns. Dinosaur literally means \"terrible lizard.\" The heart of a Sauropod dinosaur would probably have weighed a staggering one ton. A full-color, fun, and informative series, Secret Worlds offers a chance to get your teeth deep into a wide range of fascinating subjects from nature, history, and science. Every title has: Easy-to-read narrative text written by a specialist who combines expert knowledge with an entertaining and fresh style. Superb color photography that entices the reader into the subject world with close-up views and dramatic shots. Weird World feature boxes that reveal a wealth of wacky facts. Tried-and-tested websites to check out the latest info. A mega reference section with even more facts and figures for the enthusiast. Suitable for children aged ten and up -- as well as every other family member who is curious about the subject.', 'Ebook', 'Juvenile Nonfiction / Animals / Dinosaurs & Prehistoric Creatures, Juvenile Nonfiction / History / Prehistoric', 0, 12, 6, 'https://books.google.com/books/content?id=B8vdJ-1iWWUC&printsec=frontcover&img=1&zoom=1&imgtk=AFLRE70ciVT-jW1WbVgQhK9blzH7hmm1GLnr1qnkcHPl-6FK94BOLkT263Koi72B3aIJ3bl9MqqeGbEhk8jtUK5nZdtt1LqLbU7t36tU1d4k7j-jrzsxtjMhrIRUHU9rjDmYRMM1ARiP&source=gbs_api', 'leyendo', '', 96, 'B8vdJ-1iWWUC', '2001'),
(85, 'Dino bites!', 'Algy Craig Hall', 'A cumulative story finds a hungry dinosaur munching and crunching and searching for lunch until his appetite leads him to a buzzing noise, a hop, and a wriggle before he encounters a big surprise.', NULL, 'Dinosaurs, Juvenile fiction, Size, Stories in rhyme, Fiction', NULL, NULL, 6, 'https://covers.openlibrary.org/b/id/13387665-L.jpg', 'pendiente', '/works/OL19964494W', NULL, '', '2013'),
(87, 'Adultery', 'Paulo Coelho', 'Descripción no disponible', NULL, 'Married people, fiction, Politicians, fiction, Fiction, romance, contemporary, Man-woman relationships, Fiction', NULL, NULL, 22, 'https://covers.openlibrary.org/b/id/10132983-L.jpg', 'pendiente', '/works/OL20828419W', 304, '', '2015'),
(91, 'They Came to Baghdad', 'Agatha Christie', 'E-book exclusive extras: \'Agatha Christie in Baghdad,\' extensive selections from Agatha Christie: An Autobiography. Plus: Christie biographer Charles Osborne\'s essay on They Came to Baghdad.Agatha Christie first visited Baghdad as a tourist in 1927; many years later she would become a resident of the exotic and then open city, and it was here, and while on archaeological digs throughout Iraq with her husband, Sir Max Mallowan, that Agatha Christie wrote some of her most important works.They Came to Baghdad is one of Agatha Christie\'s highly successful forays into the spy thriller genre. In this novel, Baghdad is the chosen location for a secret superpower summit. But the word is out, and an underground organisation is plotting to sabotage the talks.Into this explosive situation stumbles Victoria Jones, a young woman with a yearning for adventure who gets more than she bargains for when a wounded secret agent dies in her hotel room. Now, if only she could make sense of his final words: \'Lucifer... Basrah... Lefarge...\'', 'Libro Físico', 'English Spy stories, Fiction, Mystery, Conspiracy, French literature', NULL, 24, 23, 'https://covers.openlibrary.org/b/id/12846782-L.jpg', 'leyendo', '/works/OL472215W', 199, '', '1993'),
(92, 'La casa entre los pinos', 'Ana Reyes', '<p> <b>Dos muertes súbitas y misteriosas en idénticas circunstancias.</b> </p> <p> <b>Un thriller psicológico absorbente que Reese Witherspoon seleccionó para su club de lectura.</b> </p> <p>Maya no está pasando por su mejor momento. Acaba de dejar un medicamento que regula los ataques de pánico, sufre síndrome de abstinencia, lleva días sin dormir y bebe demasiado. Por eso, cuando frente a la pantalla de su móvil revive lo ocurrido el verano de sus diecisiete años no sabe si puede confiar en la lucidez de su mente. Las imágenes de seguridad de una cafetería registran la muerte súbita de una joven. Junto a ella está Frank Bellamy. Ni siquiera se han rozado, pero Maya sabe que él es el responsable, igual que lo fue de la muerte de Aubrey siete años atrás.</p> <p>Maya no tiene otra salida que investigar sobre los enigmas del pasado para poder resolver los del presente. Y para ello tendrá que regresar a la cabaña del bosque y adentrarse en los recuerdos que la aterrorizan.</p> <p> <b>La crítica ha dicho:</b> <br> «Un misterio escalofriante sobre la memoria y el deseo». <br> <i>The Times</i> </p> <p>«Un thriller del que es imposible despegarse... Un viaje salvaje que me ha transportado volando de un capítulo al siguiente». <br> Reese Witherspoon</p> <p>«Magnífico». <br> M. W. Craven</p> <p>«Una adictiva, inteligente e inquietante historia de suspense psicológico sobre la complejidad de la amistad femenina y la fragilidad de los recuerdos». <br> Alafair Burke</p> <p>«Me encantó. Lo leí del tirón, totalmente enganchada y ansiosa por conocer la verdad». <br> Lisa Gardner</p> <p>«Una mezcla absorbente de thriller psicológico y cuento de hadas muy oscuro. Explora las múltiples maneras en que los recuerdos nos fallan y cómo pueden también liberarnos». <br> Riley Sager</p>', 'Ebook', 'Fiction / Thrillers / Psychological, Fiction / Thrillers / Supernatural', NULL, 38, 23, 'https://books.google.com/books/publisher/content?id=-rwgEQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&imgtk=AFLRE73HiqUJ83Mq81HgpdmXguq6vCkYvRx9M3RTt0pYRFX2c9BGjeTR4wVtv11BxlLNM1QTXIP57ExfJT-vOzouGIf1rqHd5ytCXsyO8fzJRsCSDXHKtv2bFe459RsLS_IaZ7_mstVT&source=gbs_api', 'leyendo', '', 338, '-rwgEQAAQBAJ', '2024-10-10'),
(95, 'La Policía de la Memoria', 'Yoko Ogawa', '<p> <b>Una poderosa y delicada novela, de tintes orwellianos, sobre el control social y la memoria.</b> </p> <p>En una pequeña isla se produce un misterioso fenómeno. Un día desaparecen los pájaros, al siguiente podría desaparecer cualquier cosa: los peces, los árboles... Peor aún, también se desvanecerá la memoria de ellos, al igual que las emociones y sensaciones que llevaban asociadas. Nadie sabrá ni recordará entonces qué eran. Hay incluso una policía dedicada a perseguir a los que conservan la capacidad de recordar lo que ya no existe. En esa isla vive una joven escritora que, tras la muerte de su madre, intenta escribir una novela mientras trata de proteger a su editor, que está en peligro porque forma parte de los pocos que recuerdan. La ayudará un anciano al que empiezan a fallarle las fuerzas. Mientras, lentamente, nuestra protagonista va dando forma a su novela: es el relato de una mecanógrafa cuyo jefe acaba reteniéndola contra su voluntad en un altillo. Una obra sobre el poder de la memoria y sobre la pérdida.</p>', NULL, 'Fiction / General', NULL, NULL, 23, 'https://books.google.com/books/publisher/content?id=Xc0QEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&imgtk=AFLRE72_7rH211KTyleZYj2O0KmxeJZgNWa2awvU3dff4RkgEia3S3bktY9cVGBck-4Ggpi0LZrSOVwewa67lsYdT5qumawviHQBPVpqPWYKMrBNWoweKm3xmLwcrpsy9kCQo_b36G1l&source=gbs_api', 'pendiente', '', 400, 'Xc0QEAAAQBAJ', '2021-02-10'),
(96, 'El invencible verano de Liliana', 'Cristina Rivera Garza', '<p> <b>«Más allá de las partes que hablan con franqueza del inmenso amor entre las hermanas, El invencible verano de Liliana es en sí mismo un acto de amor para Liliana. Una expansión de la hermandad compartida entre mujeres, que también se llama feminismo.» Nayeli García Sánchez</b> </p> <p>«El 16 de julio de 1990, <b>Liliana Rivera Garza, mi hermana, fue víctima de un feminicidio</b>. Era una muchacha de 20 años, estudiante de arquitectura. Tenía años tratando de terminar su relación con un novio de la preparatoria que insistía en no dejarla ir. La decisión de él fue que ella no tendría una vida sin él.</p> <p> <i>El invencible verano de Liliana</i> es una excavación en la vida de una mujer brillante y audaz que careció, como nosotros mismos, del lenguaje necesario para identificar, denunciar y luchar contra la violencia sexista y el terrorismo de pareja. Este libro es para celebrar su paso por la tierra y para decirle que, claro que sí, <b>al patriarcado lo vamos a tirar</b>.» Cristina Rivera Garza</p> <p>*Premio Rodolfo Walsh 2022*</p> <p>*Premio Mazatlán de Literatura 2022*</p> <p>*Premio Xavier Villaurrutia de Escritores para Escritores 2021*</p> <p>*Premio Nuevo León Alfonso Reyes 2021*</p> <p>*Premio Iberoamericano de Letras José Donoso 2021*</p>', NULL, 'Biography & Autobiography / Literary Figures, Social Science / Women\'s Studies', NULL, NULL, 23, 'https://books.google.com/books/publisher/content?id=gcUrEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&imgtk=AFLRE71TGCoRNYKakvrUkKVTxs9csWRkxJk--04yMr1tG9NgWV0nW2ns2qBpciS0krx2zczhmsJcZL7Vz0ZqAHIsZqPcECJoFYbZcJN7gPIJuqpI4YefCt2bd3pcZB7yAPH87-7VvqF6&source=gbs_api', 'pendiente', '', 304, 'gcUrEAAAQBAJ', '2021-04-23'),
(107, 'Pokémon Escuela De Entrenadores', 'ActorBrian', 'Imagina que todos los protagonista de cada videojuego de la saga pokemon lo pongamos en una jaula y lo veamos pelear. Ja-Ja-Ja no es para tanto.  Esta historia es para fanes pokemon, ¿si quieres reirte un poco y difrutar de tus entrenadores favoritos?, pues imagina que todos sean de secundaria en una clase del instituto de entrenadores pokemon, donde convivirán entre ellos en una clase lleno de las historias mas locas y divertidas que veras.  Aclaraciones:  Antes de nada me quiero asegurar de algunas cosas como ejemplo:  Para los nombres de los personajes  usare los nombre del juego, osea Serena se llamara Serena, ¡Los estoy viendo AmourShipping!, no sera la misma Serena del anime.  <Uno se va de su asiento>...  Ok, Para las personalidades me guiare del manga, Pokemon Adventure, si no lo leíste pues Looser, Nah solo bromeo, te aconsejo el manga es buenisimo y si no aparece un personaje de pokemon significa que hará su aparición pronto, con todo aclarado, disfruta de mi obra 😊. Todos los derechos reservados', 'Digital', 'fanfic, batallas, aventura, escuela, pokemon', 1, 119, 23, 'https://res.cloudinary.com/jklaybsr/image/upload/v1783792735/hpuso516nkaq6gcvqjhb.jpg', 'pendiente', NULL, 0, NULL, ''),
(108, 'El club de los poetas muertos', 'N. H. Kleinbaum', 'A una prestigiosa academia de educación más bien estricta y conservadora llega un nuevo profesor, el señor Keating, dispuesto a enseñar a los chicos nuevos metodos de aprendizaje a través de la poesía y las letras y nuevas ídeas que no congeniarán para nada con la academia, mediante el lema Carpe diem (aprovecha el tiempo) este profesor guiará a su ejercito de alumnos...y las consecuencias podrán ser trágicas... Este libro fue llevado al cine con gran éxito.', NULL, 'No disponible', 0, NULL, 23, 'https://covers.openlibrary.org/b/id/9279160-L.jpg', 'pendiente', '/works/OL20640389W', 172, '', '1991'),
(114, 'Soy un gato', 'Natsume Soseki', '\"Soy un gato, aunque todavía no tengo nombre\". Así comienza la primera y más hilarante novela de Natsume Soseki, una auténtica obra maestra de la literatura japonesa, que narra las aventuras de un desdeñoso felino que cohabita, de modo accidental, con un grupo de grotescos personajes, miembros todos ellos de la bienpensante clase media tokiota: el dispéptico profesor Kushami y su familia, teóricos dueños de la casa donde vive el gato; el mejor amigo del profesor, el charlatán e irritante Meitei; o el joven estudioso Kangetsu, que día sí, día no, intenta arreglárselas para conquistar a la hija de los vecinos. Escrita justo antes de su aclamada novela Botchan, Soy un gato es una sátira descarnada de la burguesía Meiji. Dotada de un ingenio a prueba de bombas y de un humor sardónico, recorre las peripecias de un voluble filósofo gatuno que no se cansa de hacer los comentarios más incisivos sobre la disparatada tropa de seres humanos con la que le ha tocado convivir.', NULL, 'Fiction / Literary', 0, NULL, 23, 'https://books.google.com/books/publisher/content?id=d1VVEQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&imgtk=AFLRE72b67ZouSbrFinQDe_DCsvpOLzOps-ZgHC8vjR4ZUx5q6baddTuRAGT7olLraYJMuzm7L50p4ESCuFzFmawzc3QzwAcl9qdBJc0Z_8fl_1kBmfNnP0F4kyKsHrlL9CIrKqGcWOD&source=gbs_api', 'pendiente', '', 656, 'd1VVEQAAQBAJ', '2010-04-05'),
(115, 'Sword Art Online', 'Reki Kawahara', 'Un jugador solitario llamado Kirito , que tuvo la suerte de jugar la versión beta del primer VRMMORPG, « Sword Art Online » (SAO), se encontraba entre los 10.000 jugadores atrapados en el juego durante el primer día de su lanzamiento oficial. La única forma de escapar era completar todos los pisos de Aincrad, el castillo flotante donde se desarrolla el juego, y derrotar al jefe final. Morir en el juego significaba morir en la vida real, debido al NerveGear , una consola que simulaba los controles del personaje redirigiendo las señales cerebrales. Dos años después del inicio de este juego mortal, de los diez mil jugadores originales, quedaban menos de siete mil, con veinticinco pisos por completar.', 'Digital', 'Isekai, Acción, Aventura, Fantasía, Romance', 1, 25, 23, 'https://res.cloudinary.com/jklaybsr/image/upload/v1784041241/j0zud3delzzmwadgp6s3.jpg', 'pendiente', NULL, 360, NULL, '2003'),
(119, 'El secreto', 'Donna Tartt', '<p> <b>30 ANIVERSARIO</b> <br> <b>POR LA AUTORA DE </b> <i> <b>EL JILGUERO</b> </i> <b>, GANADORA DEL PREMIO PULITZER</b> </p> <p> <p> <b>UNO DE LOS MEJORES LIBROS DE LA HISTORIA SEGÚN LOS LECTORES DE <i>THE GUARDIAN</i> </b> </p> <p> <p>«La historia del misterioso asesinato que sigue fascinando treinta años después.» <br> <b>BBC</b> </p> <p> <p>«Una auténtica maravilla. [...] Contundente, sólida e impecablemente contada.» <br> <i> <b>The New York Times</b> </i> </p> <p>«Donna Tartt es una escritora increíblemente buena: profunda, sugerente. Una narradora extraordinaria.» <br> <b>Stephen King</b> </p> <p> <p>La vida no es fácil en un college de Nueva Inglaterra si eres un chico modesto y falto de afecto que llega de California, y Richard Papen lo sabe; por eso agradece que lo admitan en un pequeño grupo de cinco estudiantes capitaneados por un profesor de literatura clásica con mucho carisma y pocos escrúpulos.</p> <p>Los chicos sueltan comentarios en griego y se ríen de la ingenuidad y la torpeza de los demás, pero bien mirado se pasan el día bebiendo y engullendo pastillas. Hasta que un mal día lo que parecían chiquilladas adquieren una gravedad inesperada. Es entonces cuando Richard y su pandilla descubren qué difícil es vivir sin máscaras y qué fácil es matar sin remordimientos.</p> <p> <i>El secreto</i>, primera novela de la gran Donna Tartt, se cuenta entre las mejores obras del siglo XX.</p> <p> <b>La crítica ha dicho:</b> <br> «Si alguna vez pensaste que estudiar Letras era solo corregir comas y leer en bata junto a una chimenea, este libro te va a sacar de tu error. <i>El secreto</i> es como si <i>El club de los poetas muertos</i> y un thriller psicológico tuvieran un hijo oscuro y elegante. Secretos y culpa para recordarte que no todo lo que brilla es oro, ni todo lo clásico es inocente.» <br> Ana Trasobares, <i>Esquire </i> </p> <p>«El único libro que desearía haber escrito». <br> Camilla Läckberg, <i>Elle</i> </p> <p>«Uno de esos libros nacidos para ser clásicos instantáneos. Una lectura perfecta para estar en el sofá, tapado, con la única necesidad de devorar sus páginas (advertencia: tiene un alto componente adictivo, que su longitud no cause rechazo a los curiosos). [...] Durante sus páginas se puede disfrutar con todo: el misterio, el lujo, amores no correspondidos... El propio college semeja un elemento vivo más. Cualquier enamorado de la estética dark academia (hola, Miércoles Adams) encontrará aquí el santo grial». <br> Alba Álvarez (autora de Pellejos), <i> Vogue</i> </p> <p>«Una novela imposible de abandonar hasta la última página.» <br> John Grisham</p> <p>«La voz de Tartt no es como la de sus contemporáneos. Su bello lenguaje, su intrincado argumento y sus fascinantes personajes ya se notan de lejos en su debut.» <br> <i>Cosmopolitan</i> </p> <p>«Vestida como un diminuto gentleman andrógino, con zapatos Oxford, chalecos y corbatas y peinada con un <i>bob </i>imperturbable (desde Tom Wolfe, ningún escritor había hecho tan bien lo del <i>autobranding</i>), a Tartt la rodeaba un relato fabuloso, una historia que se ha demostrado no del todo o casi nada cierta que hablaba de gentileza del Sur y dinero viejo. [ <i>El secreto</i>] se ha convertido en un libro de culto, muy citado, leído y disfrutado.» <br> Begoña Gómez Urzaiz, <i>El País</i> </p> <p>«Como entretenimiento de ritmo feroz, es un éxito magnífico.» <br> <i>The New York Times </i> </p> <p>«Una novela descomunal, fascinante e arrolladora.» <br> <i>Vanity Fair</i> </p> <p>«Inquietante, convincente y maravilloso. [...] Repleto de referencias literarias, con un estilo elegante y una atmósfera que recuerdan más al siglo XIX que el XX.» <br> <i>The Time</i> </p>', NULL, 'Fiction / General', 0, NULL, 23, 'https://books.google.com/books/publisher/content?id=qZ3tAgAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&imgtk=AFLRE70cWsfuo-xFkiA6OuqRZs1a4eYLh2M0tEmGDed1MAKmwW4Was00EvKgCS3-LjkffkuKYzYlPK_Ww2D_Qr-CMRwBeTCpnWwl99n_I12ANnSZwqNWxpSfwQ8cuJMs20g850JqTO2D&source=gbs_api', 'pendiente', '', 776, 'qZ3tAgAAQBAJ', '2014-03-13'),
(126, 'Jurassic Park', 'Michael Crichton', ' El multimillonario John Hammond utiliza ADN extraído de mosquitos fosilizados para clonar dinosaurios y construir un parque temático exclusivo en la Isla Nublar. Antes de abrir al público, invita a un grupo de científicos (incluyendo al matemático Ian Malcolm, el paleontólogo Alan Grant y la paleobotánica Ellie Sattler) para evaluar su seguridad. Sin embargo, la codicia y el sabotaje informático provocan que los sistemas de seguridad fallen, dejando a los visitantes atrapados junto a dinosaurios depredadores.', 'Digital', 'ciencia ficción, tecno-thriller, aventuras', 1, 68, 23, 'https://res.cloudinary.com/jklaybsr/image/upload/v1784580493/pl4rrers3feqphyjg9tl.jpg', 'pendiente', NULL, 480, NULL, '1990'),
(127, 'La máquina del tiempo', 'H. G. Wells', '<p> <b>La obra pionera de los viajes en el tiempo, escrita por uno de los padres de la ciencia ficción.</b> </p> <p> <b>Cubierta diseñada por Adrià Molins.</b> <br> <b>Traducción de José C. Vales.</b> <br> —Hace mucho tiempo tuve la idea de una máquina... <br> —¡Para viajar en el tiempo! —exclamó el jovencito. <br> —Y podría viajar absolutamente en cualquier dirección en el tiempo y en el espacio, dependiendo del gusto del piloto. <br> <i>La máquina del tiempo</i> fue la primera obra de éxito de G. H. Wells y pionera en los Viajes en el tiempo. A finales del siglo XX, un hombre idea una máquina con la que asegura poder viajar en el tiempo. Ante la incredulidad de los científicos de la época, el Viajero del Tiempo consigue llegar al futuro, donde, tras una serie de aventuras, aterrizará a un mundo aterrador habitado por unos seres extraños llamados Eloi y Morlocks.</p>', NULL, 'Fiction / Classics, Fiction / Science Fiction / General', 0, NULL, 23, 'https://books.google.com/books/publisher/content?id=KAuSDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&imgtk=AFLRE73YYy-qUX3xKZGbRIu4Hy-O0cjN292dTBG9lxTS6guHUakny_gZ4kljHK1QmwXUh_-Z6z8xnSuMUXs67v4ioyfzzKbc04cWWUPgULL4HbgZTLBw6bzWYVvIkV8ssoU8Wr0rHFAX&source=gbs_api', 'pendiente', '', 224, 'KAuSDwAAQBAJ', '2019-06-18'),
(128, 'La paciente silenciosa / The Silent Patient', 'Alex Michaelides', '<b>«El<i> thriller</i> perfecto» (según A.J. Finn, autor de<i> La mujer en la ventana</i>) que está conmocionando a treinta y siete países y cuyos derechos han sido comprados para una adaptación cinematográfica producida por Brad Pitt.<br><br></b>SOLO ELLA SABE LO QUE SUCEDIÓ.<br><br>SOLO YO PUEDO HACERLA HABLAR.<br><br>Alicia Berenson, una pintora de éxito, dispara cinco tiros en la cabeza de su marido, y no vuelve a hablar nunca más. Su negativa a emitir palabra alguna convierte una tragedia doméstica en un misterio que atrapa la imaginación de toda Inglaterra.<br><br>Theo Faber, un ambicioso psicoterapeuta forense obsesionado con el caso, está empeñado en desentrañar el misterio de lo que ocurrió aquella noche fatal y consigue una plaza en The Grove, la unidad de seguridad en el norte de Londres a la que Alicia fue enviada hace seis años y en la que sigue obstinada en su silencio. Pronto descubre que el mutismo de la paciente está mucho más enraizado de lo que pensaba. Pero, si al final hablara, ¿estaría dispuesto a escuchar la verdad?<br><br><b>ENGLISH DESCRIPTION<br><br>On the list of the Best 2019 Mystery / Thrillers Books of <i>Publishers Weekly</i></b><br><br><b>The instant #1 <i>New York Times </i>bestseller<br></b><br>\"An unforgettable―and Hollywood-bound―new thriller... A mix of Hitchcockian suspense, Agatha Christie plotting, and Greek tragedy.\". <b>―<i>Entertainment Weekly<br></i></b><br><b><i>The Silent Patient</i> is a shocking psychological thriller of a woman’s act of violence against her husband―and of the therapist obsessed with uncovering her motive.</b><br><br>Alicia Berenson’s life is seemingly perfect. A famous painter married to an in-demand fashion photographer, she lives in a grand house with big windows overlooking a park in one of London’s most desirable areas. One evening her husband Gabriel returns home late from a fashion shoot, and Alicia shoots him five times in the face, and then never speaks another word.<br><br>Alicia’s refusal to talk, or give any kind of explanation, turns a domestic tragedy into something far grander, a mystery that captures the public imagination and casts Alicia into notoriety. The price of her art skyrockets, and she, the silent patient, is hidden away from the tabloids and spotlight at the Grove, a secure forensic unit in North London.<br><br>Theo Faber is a criminal psychotherapist who has waited a long time for the opportunity to work with Alicia. His determination to get her to talk and unravel the mystery of why she shot her husband takes him down a twisting path into his own motivations―a search for the truth that threatens to consume him....', NULL, 'Fiction / Thrillers / Psychological, Fiction / Thrillers / Suspense', 0, NULL, 23, 'https://books.google.com/books/publisher/content?id=gGWREAAAQBAJ&printsec=frontcover&img=1&zoom=1&imgtk=AFLRE73l4VZwideSvGo_lQ6cKXnXoVyGLpIkoyFlQkwZPRk96UgsJ26nsBQgGes-gPOiSU4dsbs90UZ2bJTLynSwXQvTFwcG74DW5wmdZTGXRLhyxv6xrnqh93C6VK8malfe6WNWI_N0&source=gbs_api', 'pendiente', '', 384, 'gGWREAAAQBAJ', '2020-01-21'),
(130, 'El nombre del viento (Crónica del asesino de reyes 1)', 'Patrick Rothfuss', '<p> <b>Atípica, profunda y sincera, </b> <i> <b>El nombre del viento</b> </i> <b> es una novela de aventuras, de historias dentro de otras historias, de misterio, de amistad, de amor, de magia y de superación.</b> </p> <p> <p> <b>La novela que ha consagrado a Patrick Rothfuss como fenómeno editorial de los últimos años.</b> </p> <p>En una posada en tierra de nadie, un hombre se dispone a relatar, por primera vez, la auténtica historia de su vida. Una historia que únicamente él conoce y que ha quedado diluida tras los rumores, las conjeturas y los cuentos de taberna que le han convertido en un personaje legendario a quien todos daban ya por muerto: Kvothe... músico, mendigo, ladrón, estudiante, mago, héroe y asesino.</p> <p>Ahora va a revelar la verdad sobre sí mismo. Y para ello debe empezar por el principio: su infancia en una troupe de artistas itinerantes, los años malviviendo como un ladronzuelo en las calles de una gran ciudad y su llegada a una universidad donde esperaba encontrar todas las respuestas que había estado buscando.</p> <p> <b>«Viajé, amé, perdí, confié y me traicionaron».</b> </p> <p>«He robado princesas a reyes agónicos. Incendié la ciudad de Trebon. He pasado la noche con Felurian y he despertado vivo y cuerdo. Me expulsaron de la Universidad a una edad a la que a la mayoría todavía no los dejan entrar. He recorrido de noche caminos de los que otros no se atreven a hablar ni siquiera de día. He hablado con dioses, he amado a mujeres y he escrito canciones que hacen llorar a los bardos.</p> <p> <p>Me llamo Kvothe. Quizá hayas oído hablar de mí».</p> <p> <b>La crítica ha dicho...</b> <br> «Una estupenda y fuera de lo común novela de aventuras fantásticas». <br> Justo Navarro, <i>El País</i> </p> <p>«Sin duda <i>El nombre del viento</i> se convertirá en un clásico». <br> <i>The Times</i> </p> <p>«Un libro para quien conoce el mágico poder de las palabras». <br> Ricard Ruiz Garzón, <i>El Periódico de Catalunya</i> </p> <p>«Una aventura insólita y preciosa. Puntuación: Sobresaliente». <br> Manu González, <i>Qué Leer</i> </p> <p>«No sucede a menudo, pero <i>El nombre del viento</i> de Patrick Rothfuss sí es tan bueno como dicen las reseñas». <br> <i>Locus</i> </p> <p>«A veces, con suerte y unas cuantas recomendaciones de buenos amigos, se vuelve a descubrir otro paraíso en el que quedarse, un par de semanas, unos cuantos días. Y eso es justo lo que me ha pasado con <i>El nombre del viento</i>». <br> Toni Rodero, <i>La Voz de Avilés</i> </p>', NULL, 'Fiction / Fantasy / General, Fiction / Action & Adventure', 0, NULL, 23, 'https://books.google.com/books/content?id=QeYF9kTMypgC&printsec=frontcover&img=1&zoom=1&edge=curl&imgtk=AFLRE73MXtzVCieYub9rZHtYthHq7lGzi3ytUEZJyW7NFZzQ1aDiusuf7i5_5zHFRXb1naW8JVqVV4Us9ACbaikSKkKdiM3xdyFk6wTXfR4Im35yG3mGnGRusBQ_hVh69mMatCV-6aJn&source=gbs_api', 'pendiente', '', 880, 'QeYF9kTMypgC', '2011-11-18'),
(131, 'Moby Dick', 'Herman Melville', 'Este ebook presenta &quot;Moby Dick&quot;, con un indice dinámico y detallado. Moby-Dick es una novela de Herman Melville publicada en 1851. Narra la travesía del barco ballenero Pequod en la obsesiva y autodestructiva persecución de una gran ballena blanca (cachalote) impulsada por el capitán Ahab. Al margen de la persecución y evolución de sus personajes, el tema de la novela es eminentemente enciclopédico al incluir detalladas y extensas descripciones de la caza de las ballenas en el siglo XIX y multitud de otros detalles sobre la vida marinera de la época. Quizá por ello la novela no tuvo ningún éxito comercial en su primera publicación, aunque con posterioridad haya servido para cimentar la reputación del autor y situarlo entre los mejores escritoires estadounidenses. Herman Melville (1819 – 1891) - novelista y poeta norteamericano y una de las principales figuras de la historia de la literatura. Con apenas veinte años, Melville comenzó una serie de viajes por todo el mundo que más adelante le servirían como base e inspiración para varias de sus novelas, incluyendo varios años trabajando como ballenero y pasando varias aventuras en las islas del Pacífico. El mar y su mundo son fundamentales en la obra de Melville, como ya se aprecia en Mardi o Taipi.', NULL, 'Fiction / Classics, Fiction / Literary', 0, NULL, 23, 'https://books.google.com/books/publisher/content?id=4KJjDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&imgtk=AFLRE70MfFVJyjVOE04PMYVzrtYOiMzkr_xMSu75U2TK49WneHtzrwkKSLzX-wxQddZ-sTidjhCCbiRWc-KZjitZTIbLJ8TPb-dgLxNOKUPpmp5DeeGF5D_FKmZS14LesNzuBfaWBwpe&source=gbs_api', 'pendiente', '', 599, '4KJjDwAAQBAJ', '2013-11-27'),
(142, 'El Principito', 'Antoine De Sain Exupery', '«El Principito habita un pequeñísimo asteroide, que comparte con una flor caprichosa y tres volcanes. Pero tiene \"problemas\" con la flor y empieza a experimentar la soledad. Hasta que decide abandonar el planeta en busca de un amigo. Buscando esa amistad recorre varios planetas, habitados sucesivamente por un rey, un vanidoso, un borracho, un hombre de negocios, un farolero, un geógrafo... El concepto de \"seriedad\" que tienen estas \"personas mayores\" le deja perplejo y confuso. Prosiguiendo su búsqueda llega al planeta Tierra, pero, en su enorme extensión y vaciedad, siente más que nunca la soledad. Una serpiente le da su versión pesimista sobre los hombres y lo poco que se puede esperar de ellos. Tampoco el zorro contribuye a mejorar su opinión, pero en cambio le enseña el modo de hacerse amigos: hay que crear lazos, hay que dejarse \"domesticar\". Y al final le regala su secreto: \"Sólo se ve bien con el corazón. Lo esencial es invisible a los ojos\". De pronto el Principito se da cuenta de que su flor le ha \"domesticado\" y decide regresar a su planeta valiéndose de los medios expeditivos que le ofrece la serpiente. Y es entonces cuando entra en contacto con el aviador, también el hombre habrá encontrado un amigo...»Cuando yo tenía seis años vi en un libro sobre la selva virgen que se titulaba \"Historias vividas\", una magnífica lámina. Representaba una serpiente boa que se tragaba a una fiera. Esta es la copia del dibujo.En el libro se afirmaba: \"La serpiente boa se traga su presa entera, sin masticarla. Luego ya no puede moverse y duerme durante los seis meses que dura su digestión\".Reflexioné mucho en ese momento sobre las aventuras de la jungla y a mi vez logré trazar con un lápiz de colores mi primer dibujo. Mi dibujo número uno era de esta manera: Enseñé mi obra de arte a las personas mayores y les pregunté si mi dibujo les daba miedo.-¿por qué habría de asustar un sombrero? - me respondieron.Mi dibujo no representaba un sombrero. Representaba una serpiente boa que digiere un elefante. Dibujé entonces el interior de la serpiente boa a fin de que las personas mayores pudieran comprender. Siempre estas personas tienen necesidad de explicaciones. Mi dibujo número dos era así: Las personas mayores me aconsejaron abandonar el dibujo de serpientes boas, ya fueran abiertas o cerradas, y poner más interés en la geografía, la historia, el cálculo y la gramática. De esta manera a la edad de seis años abandoné una magnífica carrera de pintor. Había quedado desilusionado por el fracaso de mis dibujos número uno y número dos. Las personas mayores nunca pueden comprender algo por sí solas y es muy aburrido para los niños tener que darles una y otra vez explicaciones.', 'Novela Gráfica', 'Juvenile Fiction / Humorous Stories', 0, NULL, 63, 'https://books.google.com/books/content?id=0y3rsgEACAAJ&printsec=frontcover&img=1&zoom=1&imgtk=AFLRE70ro-trL50ZAWd8tM3KLvQchfs3kdAlk3Ax9ekcp3juFwlaHScDO51eU0ccLgoIXc5BfflkyQZb4B8jbCmKTdQJUQZ1xZ_eEZxqWLFXMvFr04vWyrkHO_uWRIx0R4I6_SDkLW8P&source=gbs_api', 'leyendo', '', 128, '0y3rsgEACAAJ', '2015-06-10'),
(143, 'Cuentos de los Hermanos Grimm', 'Hermanos Grimm', '<p> <b>Selección de los quince cuentos originales más influyentes de los Hermanos Grimm. Esta edición contiene los textos tal como los escribieron sus autores, muy diferentes a los que se popularizaron. En muchos casos, sorprenderán a los lectores. Traducción de Isabel HernándezCubierta diseñada por Lorena G.Ilustraciones de interior: Otto Ubberlohde</b> </p> <p>Brujas, pillos, animales parlanchines, sapos besucones, enanos, princesas, príncipes... Los cuentos de los Hermanos Grimm han servido de inspiración para numerosas adaptaciones fílmicas para los más pequeños, en gran medida transformadas y embellecidas. En esta edición, el lector tanto joven como adulto tiene la oportunidad de conocer quince cuentos originales en una nueva traducción a cargo de Isabel Hernández: «El rey sapo o Enrique el de hierro», «Cuento de uno que se marchó a aprender lo que era el miedo», «El lobo y los siete cabritillos», «Rapunzel», «Las tres hilanderas», «Hansel y Gretel», «El pescador y su mujer», «El sastrecillo valiente», «Cenicienta», «Caperucita Roja», «Los músicos de Bremen». «Pulgarcito», «La bella durmiente», «Blancanieves» y «Rumpelstiltskin».</p>', NULL, 'Juvenile Fiction / Classics, Fiction / General', 0, NULL, 63, 'https://books.google.com/books/publisher/content?id=_jduDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&imgtk=AFLRE70pAaj1qHVVwd9BZpncqDNpuHfB6M7HovNfRIZMMMl5Ajd5EwoH75wKKv2ZDw5iohcg1cBvd947LRceFthFeGPyrHPkTMGiBnX0tMIwbFVXPBL_eZS3qYZ8AIoZLwTG6mdV1js3&source=gbs_api', 'pendiente', '', 224, '_jduDwAAQBAJ', '2018-10-23'),
(144, 'Crepúsculo (Saga Crepúsculo 1)', 'Stephenie Meyer', '<p><b>«Hay tres cosas de las que estoy completamente segura. Primera, Edward es un vampiro. Segunda, una parte de él se muere por beber mi sangre. Y tercera, estoy total y perdidamente enamorada de él.»</b></p> <p>Cuando Isabella Swan se muda a Forks, una pequeña localidad del estado de Washington donde no deja de llover, piensa que es lo más aburrido que le podía haber ocurrido. Pero su vida da un giro excitante y aterrador una vez que se encuentra con el misterioso y seductor Edward Cullen. Hasta ese momento, Edward se las había arreglado para mantener en secreto su identidad vampírica, pero ahora ya nadie está a salvo, ni siquiera la persona a quien él más quiere: Isabella.</p> <p><b>** Número 1 en la lista de <i>bestsellers</i> de <i>The New York Times</i> y del <i>USA Today</i>.</b><br><b>** Mejor Novela Young Adult de Todos los Tiempos por la revista <i>Time</i>.</b><br><b>** NPR a la Mejor Novela Adolescente.</b><br><b>** Recomendada por el editor de <i>The New York Times</i>.</b></p> <p>La «Saga Crepúsculo», en la que se incluyen los títulos <i>Crepúsculo</i>, <i>Luna nueva</i>, <i>Eclipse</i>, <i>Amanecer</i>, <i>La segunda vida de Bree Tanner</i> y la <i>Guía ilustrada oficial</i>, ha vendido ya cerca de 155 millones de copias en todo el mundo y más de 3 millones de ejemplares solo en España.</p>', NULL, 'Juvenile Fiction / Love & Romance', 0, NULL, 63, 'https://books.google.com/books/content?id=a_6j9IHQ2NkC&printsec=frontcover&img=1&zoom=1&edge=curl&imgtk=AFLRE73I3tTHTKoQlygmXQY9J3s-9_YmJMGqhcivlBfFFZj0dCPqpAkO3TDcutyE1uDHwWQI5qD5-pWfVe18aONnpKy4OzINj4os1xcbWMOuOSfOEFTAp9qonUjxhlGH5fdf4wHR70Xf&source=gbs_api', 'pendiente', '', 512, 'a_6j9IHQ2NkC', '2010-12-10'),
(145, 'Cincuenta sombras más oscuras (Movie Tie-In) / Fifty Shades Darker (MTI)', 'E L James', 'Intimidada por las peculiares prácticas eróticas y los oscuros secretos del atractivo y atormentado empresario Christian Grey, la joven Anastasia Steele decide romper con él. Pero el deseo por Christian todavía domina cada uno de sus pensamientos y, cuando finalmente él le propone retomar su aventura, Ana no puede resistirse. Sin embargo, al reanudar su tórrida y sensual relación, Ana averiguará aún más del doloroso pasado del impetuoso y exigente Cincuenta Sombras, como ella le llama. Mientras Christian lucha contra sus propios demonios, Ana debe enfrentarse a la ira y la envidia de las mujeres que la precedieron y tomar la decisión más importante de su vida. <br><br><b><br>ENGLISH DESCRIPTION<br><br>THE OFFICIAL FIFTY SHADES DARKER MOVIE TIE-IN EDITION<br>A MAJOR MOTION PICTURE<br>OFFICIAL MOVIE TIE-IN EDITION, INCLUDES BONUS MATERIAL </b> <br><br>A special edition of E L James’s #1 New York Times bestselling novel, Fifty Shades Darker, that includes her own photos and caption commentary from the making of the film.<br>Daunted by the singular tastes and dark secrets of the beautiful, tormented young entrepreneur Christian Grey, Anastasia Steele has broken off their relationship. But desire for Christian still dominates her every waking thought, and when he proposes a new arrangement, Ana cannot resist. They rekindle their searing sensual affair, and Ana learns more about the harrowing past of her damaged, driven, and demanding Fifty Shades. While Christian wrestles with his inner demons, Ana must confront the anger and envy of the women who came before her, and make the most important decision of her life.  The second volume in The Fifty Shades of Grey Trilogy.', NULL, 'Fiction / Romance / Erotic, Fiction / Erotica / General, Fiction / Women', 0, NULL, 63, 'https://books.google.com/books/publisher/content?id=mOKNEAAAQBAJ&printsec=frontcover&img=1&zoom=1&imgtk=AFLRE726IYmE0AUEH1rQ4oT2AcRwQwsgaISMMEPXJTsst_MWnJpNr-FKlZohRifZvcSP324R0rWOKiQAjdjdDI_9zOveKVnec05xw-0YU3oMReTsgZ0Rejr2QOhDg70zJF1irGxnCoL5&source=gbs_api', 'pendiente', '', 592, 'mOKNEAAAQBAJ', '2017-01-03'),
(150, 'It', 'Stephen King', 'Soon to be a major motion picture—from master storyteller Stephen King comes his classic #1 <i>New York Times</i> bestseller!<br><br>Can an <i>entire city</i> be haunted? The Losers’ Club of 1958 seems to think so. After all, when they were teenagers back then, these seven friends who called the small New England metropolis of Derry their home had first-hand experience with what made this place so horribly different. Every twenty-seven years, something that has existed here for a very long time comes back to terrorize Derry, lurking in the city storm drains and sewers, taking the shape of every nightmare and deepest dread. And yet, time passed and the children grew up, moved away...the horror of what they all experienced buried deep, wrapped in forgetfulness. Now nearly thirty years later, they’re all being called back to Derry for a final life-or-death confrontation with a primordial evil that stirs and coils in the sullen depths of their memories. For the Losers’ Club and the thing known only as “It” have some unfinished business with each other….', NULL, 'Fiction / Horror / General, FICTION / Literary, Fiction / Thrillers / Suspense, Fiction / Coming of Age', 0, NULL, 32, 'https://books.google.com/books/publisher/content?id=fVWQDQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&imgtk=AFLRE71LBdb9HIcWfZ3u-CG_e-9eh6mjxsKx2EswukJbGUJluHLxavW33g_YKOalHnUIJyWy7b6BFfZf_NqAWxTU0U71DXCw_r4hdIs7OdTlF2nBsRklwo3wGvBGAYQTatO7_phYUPd3&source=gbs_api', 'pendiente', '', 1138, 'fVWQDQAAQBAJ', '1986'),
(151, 'El resplandor', 'Stephen King', '<p>Jack Torrance está en busca de un nuevo comienzo en su vida. Su esposa quiere mantener a la familia unida. Y su pequeño hijo, Danny, es el único en darse cuenta del mal que los acecha. “REDRUM”. Esa es la palabra que Danny había visto en el espejo. Y, aunque no sabía leer, entendió que era un mensaje de horror. Danny tenía cinco años, y a esa edad pocos niños saben que los espejos invierten las imágenes y menos aún saben diferenciar entre realidad y fantasía. Pero Danny tenía pruebas de que sus fantasías relacionadas con el resplandor del espejo acabarían cumpliéndose: REDRUM... MURDER, asesinato. Su padre necesitaba aquel trabajo en el hotel. Danny sabía que su madre pensaba en el divorcio y que su padre se obsesionaba con algo muy malo, tan malo como la muerte y el suicidio. Sí, su padre necesitaba aceptar la propuesta de cuidar de aquel hotel de lujo de más de cien habitaciones, vacío y aislado por la nieve durante seis meses. Hasta el deshielo iban a estar solos. ¿Solos?...</p>', NULL, 'Fiction / Horror / General, Fiction / Thrillers / Psychological', 0, NULL, 32, 'https://books.google.com/books/publisher/content?id=hGwZEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&imgtk=AFLRE71K8E96-GzQXAJiu6sg6TF7nwyPaJhDupzLu90NPxhupy2tIAIqUf5GObCiwpm36BTJJjL5W_wHx9_MmNjncCMoph56KTv0-9il3-du38gezdhjkHC97_Hjs8r6jq0-i-DZhLF2&source=gbs_api', 'leyendo', '', 688, 'hGwZEAAAQBAJ', '2020-08-25'),
(154, 'La Cúpula / Under the Dome', 'Stephen King', '<b>Una historia apocalíptica e hipnótica. </b><br> <br>Es una soleada mañana de otoño en la pequeña ciudad de Chester’s Mill, Claudette Sanders disfruta de su clase de vuelo y Dale Barbara, hace autostop en las afueras. Ninguno de los dos llegará a su destino.<br><br>De la nada ha caído sobre la ciudad una barrera invisible como una burbuja cristalina inquebrantable. Al descender, ha cortado por la mitad a una marmota y ha amputado la mano a un jardinero. El avión que pilotaba Claudette ha chocado contra la cúpula y se ha precipitado al suelo envuelto en llamas. Dale Barbara, veterano de la guerra de Irak, debe regresar ahora a Chester’s Mill, el lugar que tanto deseaba abandonar.<br><br>El ejército pone a Dale al cargo de la situación pero Big Jim Rennie, el hombre que tiene un pie en todos los negocios sucios de la ciudad, no está de acuerdo; la cúpula podría ser la respuesta a sus plegarias.<br><br>A medida que la comida, la electricidad y el agua escasean, los niños comienzan a tener premoniciones escalofriantes. El tiempo se acaba para aquellos que viven bajo la cúpula. ¿Podrán averiguar qué ha creado tan terrorífica prisión antes de que sea demasiado tarde?<br><br><b>ENGLISH DESCRIPTION</b><br><br><b>An apocalyptic and hypnotic story.<br><br></b>One sunny autumn morning, in the small town of Chester’s Mill, Claudette Sanders enjoys her flying lesson, and Dale Barbara hitchhikes just outside of town. None of them will reach their destination.<br><br>Out of nowhere, an invisible barrier descend son the city like a crystalline and unbreakable bubble. While coming down, it cuts a groundhog in half and amputates a gardener’s hand. The plain Claudette was flying crashes into the dome and plummets to the ground engulfed in flames. Dale Barbara, Iraq war veteran, must return now to Chester’s Mill, the place he so wished to leave.<br><br>The military puts Dale in charge of the situation, but Big Jim Rennie, the man with one foot in every dirty business in town, does not agree. The dome might just be the answer to his prayers.<br><br> As food, power, and water become scarce, children start having chilling premonitions. Time is running out for those under the dome. Will they be able to figure out what created such terrifying prison before it’s too late?', 'Libro Físico', 'Fiction / Horror / General, Fiction / Thrillers / Psychological, Fiction / Thrillers / Suspense', 0, NULL, 45, 'https://books.google.com/books/publisher/content?id=izKOEAAAQBAJ&printsec=frontcover&img=1&zoom=1&imgtk=AFLRE70YH2Zhjy1cljHhl8I8j_PpHjW6KwOIt78Fhikz_LNsLjq_6K5Ida_dzpMyhI_LonEHIez1ftr9WjfXkB3cc_wXwdxH5OT1UjbcYwt5acuD1I1sa7rpwZm-QZpH5joIuJO-JYKw&source=gbs_api', 'pendiente', '', 1136, 'izKOEAAAQBAJ', '2022-01-18'),
(156, 'Ensayo sobre la ceguera', 'José Saramago', '<p> <b>2022: AÑO SARAMAGO</b> </p> <p> <b>Una novela</b> <b>y</b> <b>un autor que nos alertan sobre «la responsabilidad de tener ojos cuando otros los perdieron».</b> </p> <p> <i>«Dentro de nosotros hay algo que no</i> <i>tiene nombre, esa cosa es lo que somos».</i> </p> <p>Un hombre parado ante un semáforo en rojo se queda ciego súbitamente. Es el primer caso de una «ceguera blanca» que se expande de manera fulminante. Internados en cuarentena o perdidos en la ciudad, los ciegos tendrán que enfrentarse con lo más primitivo en la naturaleza humana: la voluntad de sobrevivir a cualquier precio.</p> <p> <i>Ensayo sobre la ceguera</i> es la ficción de un autor que nos alerta sobre «la responsabilidad de tener ojos cuando otros los perdieron». José Saramago traza en este libro una imagen aterradora y conmovedora de los tiempos que estamos viviendo. En un mundo así, ¿cabrá alguna esperanza?</p> <p>El lector conocerá una experiencia imaginativa única. En un punto donde se cruzan literatura y sabiduría, José Saramago nos obliga a parar, cerrar los ojos y ver. Recuperar la lucidez y rescatar el afecto son dos propuestas fundamentales de una novela que es, también, una reflexión sobre la ética del amor y la solidaridad.</p> <p> <b>La crítica ha dicho:</b> <br> «Una metáfora que, cuando se publicó, lo mismo podía valer para el sida que para el abandono de los mayores. En esta novela, la ceguera llega sin avisar y produce un deslumbramiento blanco permanente. De nuevo, desfilan lo mejor y lo peor de la especie. Como en las guerras». <br> Tereixa Constenla, <i> El País</i> </p> <p>«Saramago siempre ha demostrado una imaginación audaz como novelista. Ésta es su obra más sorprendente e inquietante». <br> Harold Bloom</p> <p>«No hay cinismo ni moraleja, sólo un reconocimiento lúcido y compasivo de las cosas tal como son, una cualidad que sólo puede calificarse honestamente como sabiduría». <br> <i>The New York Times</i> </p> <p>«Hay novelas, como ésta, que después de leídas continuarán iluminando túneles en la conciencia, abriendo puertas de habitaciones a las que no nos habíamos asomado pese a estar dentro de nosotros». <br> Juan José Millás</p> <p>«Saramago vuelve comprensible una realidad huidiza, con parábolas sostenidas por la imaginación, la compasión y la ironía». <br> Comité Nobel</p> <p>«Un hombre con una sensibilidad y una capacidad de ver y de entender que están muy por encima de lo que en general vemos y entendemos los comunes mortales». <br> Héctor Abad Faciolince</p> <p>«Saramago es un ejemplo, un estilo dignísimo de vida y literatura, que demuestra la posibilidad de navegar a contracorriente [...]. Su palabra tiene el valor de un anticongelante, de un remedio personal contra los vendavales de cinismo que nos envuelven». <br> Luis García Montero</p> <p>«Yo no sé, ni quiero saberlo, de dónde ha sacado Saramago ese diabólico tono narrativo, duro y piadoso a un tiempo, [...] que le permite contar tan cerca del corazón y a la vez tan cerca de la historia». <br> Luis Landero</p> <p>«Saramago escribe novelas sobre los mitos para desmitificarlos, [...] siempre para abordar la realidad que le rodea, para tratar de los problemas actuales que son de todos, y para que todo quede claro desde el principio». <br> Rafael Conte, <i>Babelia</i> </p> <p>«Como Günter Grass o Cees Nooteboom, Saramago aspira a enlazar con un público que desborde límites nacionales». <br> <i>El País</i> </p>', 'Ebook', 'Fiction / Literary', 0, 16, 23, 'https://books.google.com/books/content?id=tKjAj5rDY0sC&printsec=frontcover&img=1&zoom=1&edge=curl&imgtk=AFLRE70uNxwRqU9hDnpeEXRoqEkxCk7tKjOn7LmRuHPOFtKdADnPunC03PmgWCAudhYb2L-e0JfLepwk2_Y8V8MB28A5V2FSNtY-kKHtJ2Xhd2Yqn45LyH5zVJbRyL0xIVSdvmpnCYxo&source=gbs_api', 'leyendo', '', 367, 'tKjAj5rDY0sC', '2010-07-15'),
(157, 'Noches blancas', 'Fiódor Dostoievski', 'San Petersburgo, su luz, sus casas y sus avenidas son el escenario de esta apasionada novela. En una de esas «noches blancas» que se dan en la ciudad rusa durante la época del solsticio de verano, un joven solitario e introvertido narra cómo conoce de forma accidental a una muchacha a la orilla del canal. Tras el primer encuentro, la pareja de desconocidos se citará las tres noches siguientes, noches en las que ella, de nombre Nástenka, relatará su triste historia y en las que harán acto de presencia, de forma sutil y envolvente, las grandes pasiones que mueven al ser humano: el amor, la ilusión, la esperanza, el desamor, el desengaño.', 'Libro Físico', 'Comics & Graphic Novels / General, Comics & Graphic Novels / Crime & Mystery, Comics & Graphic Novels / Erotica, Comics & Graphic Novels / Fantasy / General, Comics & Graphic Novels / Horror, Comics & Graphic Novels / Media Tie-In, Comics & Graphic Novels', 0, NULL, 23, 'https://books.google.com/books/publisher/content?id=mfA0CgAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&imgtk=AFLRE70xqqz9jfJ4IbUA0CNKKEeAN-P-WyeXvRpE4e05cSE5MMBm8GDJ8cGs0D53sdRPSv_pblknHxV8xGCLqHK9jl8C_-D3FxMMwVpeFJKC2xecB1_z5jTwPHPwAotbtGl-o-PBC5ZM&source=gbs_api', 'leido', '', 84, 'mfA0CgAAQBAJ', '2015-07-15');
INSERT INTO `libros` (`id_libro`, `titulo`, `autor`, `descripcion`, `formato`, `genero`, `es_agregado_manualmente`, `num_caps`, `id_usuario`, `portada`, `categoria`, `key_libro`, `paginas_totales`, `id_google`, `anio`) VALUES
(158, 'La ciudad y la ciudad', 'China Miéville', '<p> <b>La mítica novela en que se basa la nueva serie homónima de la BBC. Por una de las mayores voces de las letras anglosajonas del siglo XXI.</b> </p> <p> <b>Galardonada con los premios Hugo, World Fantasy, BSFA, Locus y Arthur C. Clarke.</b> </p> <p>Originalmente publicada en 2009, <i>La ciudad y la ciudad</i> es la obra maestra que ha convertido a China Miéville en una de las mayores voces de las letras anglosajonas actuales en cualquier género, admirado por escritores de la talla de Carlos Ruiz Zafón, Neil Gaiman y Ursula K. Le Guin.</p> <p>Bienvenidos a la historia de dos ciudades gemelas, invisibles la una para la otra, cuyos destinos se entrelazan por el asesinato de la joven Mahalia Geary, hallada muerta y con la cara desfigurada en la ciudad de Beszel.</p> <p>Durante la investigación del crimen, el inspector Borlú seguirá las piras desde Beszel hasta la idéntica ciudad vecina, UI Qoma. Allí descubrirá la participación de la joven en una conspiración política y se verá rodeado de nacionalistas, que intentan destruir la ciudad gemela, y de unificacionistas, que sueñan con convertir las dos ciudades en una. Las verdades que el detective descubrirá sobre la separación de ambas urbes podrían constarle la vida.</p> <p>China Miéville mezcla lo mejor de la ciencia ficción, la novela negra y el drama policial en una obra que rompe las costuras de tres géneros para convertirse en una obra de lectura absolutamente inolvidable.</p> <p> <b>La crítica ha dicho...</b> <br> «Miéville no pertenece a la familia de los ingenieros de la ciencia ficción, sino a la de sus poetas.» <br> <i>Babelia</i> </p> <p>«Ficción para el nuevo siglo.» <br> Neil Gaiman</p> <p>«Si Philip K. Dick y Raymond Chandler tuvieran un hijo criado por Franz Kafka, escribiría algo parecido a <i>La ciudad y la ciudad </i>.» <br> <i>Los Angeles Times</i> </p>', 'Libro Físico', 'Fiction / Science Fiction / General', 0, NULL, 23, 'https://books.google.com/books/publisher/content?id=JFhVDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&imgtk=AFLRE73B24B98JlK4Bj3pY_K-KmLwaee7JXTJUYNzLF7QENduSLnm6eVuJz6hYKIkYn1dUi0cDEFTJXZ6I7tuChn2mwGrmq0cgxdB1RLciyKHsTw76ikCsQ9saMrNBeU_kc91e0ploId&source=gbs_api', 'inconcluso', '', 400, 'JFhVDwAAQBAJ', '2018-05-10'),
(160, 'El Parque Jurásico', 'Michael Crichton', 'Descripción no disponible', 'Libro Físico', NULL, 0, NULL, 50, 'https://books.google.com/books/content?id=bPgXJwuGZpYC&printsec=frontcover&img=1&zoom=1&imgtk=AFLRE70hTDpUQXaSXANHO7yuHCHS6uCUHU-45D6QJuEF861OhZ3erMUP47SGDQzRBzO2T5nYg2FvLtzUIhVSYjge5fs8vV_uJvzJeI9fHV6huxUXcvu-vmwQ_yv4llZtUXgNeljH5Bmq&source=gbs_api', 'leyendo', '', 443, 'bPgXJwuGZpYC', '1991'),
(161, 'Nacidos de la Bruma / Mistborn', 'Brandon Sanderson', '<b>Mistborn es la saga que ha convertido a Brandon Sanderson en el gran autor de fantasía del siglo XXI. Más de diez millones de ejemplares vendidos en todo el mundo.<br></b><br> «Una de las mejores obras de fantasía jamás escrita.» - <b><i>Forbes<br></i></b><br> <b>Las brumas gobiernan la noche. El lord Legislador domina el mundo.<br></b><br> En otros tiempos, un héroe se alzó para salvar la humanidad. Fracasó.<br> Desde entonces, el mundo es un erial de ceniza y niebla gobernado por un emperador inmortal conocido como el lord Legislador.<br> <br> Pero la esperanza perdura. Una nueva revuelta cobra forma cimentándose en la treta definitiva: la astucia de un brillante genio del crimen y la determinación de una heroína insólita, una joven ladrona callejera que deberá aprender a controlar el poder de los nacidos de la bruma.<br> <br> <b>ENGLISH DESCRIPTION</b><br> <br> <b>Now with over 10 million copies sold, The Mistborn Series has the thrills of a heist story, the twistiness of political intrigue, and the epic scale of a landmark fantasy saga.</b><br> <br> Once, a hero arose to save the world. He failed.<br> <br> Ever since, the world has been a wasteland of ash and mist controlled by the immortal emperor known as the Lord Ruler.<br> <br> But hope survives. A new uprising is forming, one built around the ultimate caper, the cunning of a brilliant criminal mastermind, and the determination of an unlikely heroine: a street urchin who must learn to master the power of a Mistborn.', 'Libro Físico', 'Comics & Graphic Novels / Adaptations, Fiction / Fantasy / Epic, Fiction / Fantasy / Action & Adventure', 0, NULL, 49, 'https://books.google.com/books/content?id=WnJg0QEACAAJ&printsec=frontcover&img=1&zoom=1&imgtk=AFLRE70NhoAi3p3nhV8vlqbbbZVf0itRuiNj3eHLwUJCnOStYbnhOmcLMzDKa5F5PXNEgO6Mrdb6x7-_0___yLVJdyI25PprbnMqxbDfChg2IDCmijCjJDt7TqzkAqW_x-QqJvczjisv&source=gbs_api', 'leyendo', '', 680, 'WnJg0QEACAAJ', '2025-10-21'),
(162, 'Nacidos de la Bruma / Mistborn', 'Brandon Sanderson', '<b>Mistborn es la saga que ha convertido a Brandon Sanderson en el gran autor de fantasía del siglo XXI. Más de diez millones de ejemplares vendidos en todo el mundo.<br></b><br> «Una de las mejores obras de fantasía jamás escrita.» - <b><i>Forbes<br></i></b><br> <b>Las brumas gobiernan la noche. El lord Legislador domina el mundo.<br></b><br> En otros tiempos, un héroe se alzó para salvar la humanidad. Fracasó.<br> Desde entonces, el mundo es un erial de ceniza y niebla gobernado por un emperador inmortal conocido como el lord Legislador.<br> <br> Pero la esperanza perdura. Una nueva revuelta cobra forma cimentándose en la treta definitiva: la astucia de un brillante genio del crimen y la determinación de una heroína insólita, una joven ladrona callejera que deberá aprender a controlar el poder de los nacidos de la bruma.<br> <br> <b>ENGLISH DESCRIPTION</b><br> <br> <b>Now with over 10 million copies sold, The Mistborn Series has the thrills of a heist story, the twistiness of political intrigue, and the epic scale of a landmark fantasy saga.</b><br> <br> Once, a hero arose to save the world. He failed.<br> <br> Ever since, the world has been a wasteland of ash and mist controlled by the immortal emperor known as the Lord Ruler.<br> <br> But hope survives. A new uprising is forming, one built around the ultimate caper, the cunning of a brilliant criminal mastermind, and the determination of an unlikely heroine: a street urchin who must learn to master the power of a Mistborn.', 'Libro Físico', 'Comics & Graphic Novels / Adaptations, Fiction / Fantasy / Epic, Fiction / Fantasy / Action & Adventure', 0, NULL, 48, 'https://books.google.com/books/content?id=WnJg0QEACAAJ&printsec=frontcover&img=1&zoom=1&imgtk=AFLRE70NhoAi3p3nhV8vlqbbbZVf0itRuiNj3eHLwUJCnOStYbnhOmcLMzDKa5F5PXNEgO6Mrdb6x7-_0___yLVJdyI25PprbnMqxbDfChg2IDCmijCjJDt7TqzkAqW_x-QqJvczjisv&source=gbs_api', 'leyendo', '', 680, 'WnJg0QEACAAJ', '2025-10-21'),
(163, 'Así es la puta vida', 'Jordi Wild', '<p> <b>El esperado libro de Jordi Wild, uno de los youtubers más populares de España y creador de</b> <i> <b> The Wild Project</b> </i> <b>, el pódcast más escuchado.</b> </p> <p> <b>Ni eres el centro del universo ni todos tus sueños</b> <b>van a cumplirse. Olvídate de las chorradas de los</b> <b>libros de autoayuda y de los gurús baratos que intentan</b> <b>hacerte creer que «si quieres, puedes»; de los</b> <i> <b>crypto bros</b> </i> <b> que te harán millonario sin trabajar y</b> <b>de los que te dicen que seas tu propio jefe mientras</b> <b>se graban en la piscina de la casa de sus padres.</b> </p> <p>Aquí no encontrarás recetas mágicas ni los cinco pasos que tienes que seguir para SER FELIZ. Eso se lo dejo a los que se quieren aprovechar de ti.</p> <p>En este libro te voy a contar lo que para mí es la vida de verdad, sin edulcorantes ni azúcares añadidos; la jodida (y maravillosa) lucha que tienes que librar cada día para poder disfrutar y realizarte. La vida te dará una buena somanta de hostias, eso es inevitable, pero de ti depende levantarte y seguir guerreando. Vale la pena, te lo aseguro.</p> <p> <p> <b>ASÍ ES LA PUTA VIDA.</b> <b>ESPERO QUE ESTÉS PREPARADO</b> <b>PARA ACEPTARLO.</b> </p>', 'Libro Físico', 'Psychology / General, Psychology / Essays', 0, NULL, 47, 'https://books.google.com/books/publisher/content?id=72-JEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&imgtk=AFLRE71r3ZAcNoHk7Mf0meDtrob8KE6hdH5trrXWRgLe2qZf826KIKI03GP1kjUfRZKB6MBQTJWSa7B_1zJHlaJlFOMG_AXcrhe7JXOmGLC37ogtryETNOTBN-VX1aG6CsUpAVfur4od&source=gbs_api', 'leyendo', '', 208, '72-JEAAAQBAJ', '2022-11-03'),
(164, 'Así es la puta vida', 'Jordi Wild', '<p> <b>El esperado libro de Jordi Wild, uno de los youtubers más populares de España y creador de</b> <i> <b> The Wild Project</b> </i> <b>, el pódcast más escuchado.</b> </p> <p> <b>Ni eres el centro del universo ni todos tus sueños</b> <b>van a cumplirse. Olvídate de las chorradas de los</b> <b>libros de autoayuda y de los gurús baratos que intentan</b> <b>hacerte creer que «si quieres, puedes»; de los</b> <i> <b>crypto bros</b> </i> <b> que te harán millonario sin trabajar y</b> <b>de los que te dicen que seas tu propio jefe mientras</b> <b>se graban en la piscina de la casa de sus padres.</b> </p> <p>Aquí no encontrarás recetas mágicas ni los cinco pasos que tienes que seguir para SER FELIZ. Eso se lo dejo a los que se quieren aprovechar de ti.</p> <p>En este libro te voy a contar lo que para mí es la vida de verdad, sin edulcorantes ni azúcares añadidos; la jodida (y maravillosa) lucha que tienes que librar cada día para poder disfrutar y realizarte. La vida te dará una buena somanta de hostias, eso es inevitable, pero de ti depende levantarte y seguir guerreando. Vale la pena, te lo aseguro.</p> <p> <p> <b>ASÍ ES LA PUTA VIDA.</b> <b>ESPERO QUE ESTÉS PREPARADO</b> <b>PARA ACEPTARLO.</b> </p>', 'Libro Físico', 'Psychology / General, Psychology / Essays', 0, NULL, 46, 'https://books.google.com/books/publisher/content?id=72-JEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&imgtk=AFLRE71r3ZAcNoHk7Mf0meDtrob8KE6hdH5trrXWRgLe2qZf826KIKI03GP1kjUfRZKB6MBQTJWSa7B_1zJHlaJlFOMG_AXcrhe7JXOmGLC37ogtryETNOTBN-VX1aG6CsUpAVfur4od&source=gbs_api', 'leyendo', '', 208, '72-JEAAAQBAJ', '2022-11-03'),
(165, 'Historia de la medicina', 'William Rojas', 'Esta obra va dirigida a los jóvenes que inician sus estudios de Medicina. El currículo de estudios médicos es muy recargado y el tiempo disponible, muy limitado. El autor pretende dar, en pocas páginas, la información básica que les permita formarse una idea del origen de la evolución de la ciencia y el arte de la medicina. Se observará, por ejemplo, cómo las mentes privilegiadas y la tenacidad y la curiosidad de dos médicos rurales y de un monje profesor de escuela secundaria, lograron establecer las bases de tres aspectos fundamentales de la medicina, la inmunología, la microbiología y la genética. Refiriéndose a Edward Jenner, Robert Koch y Gregor Mendel. Se quiere resaltar que este trabajo no es una historia de la medicina, sino un manual que resume los aspectos más destacados, Un abreboca para jóvenes con mentes inquietas. La información que se da no es completa. En muchos casos se menciona solo al protagonista principal de un descubrimiento o de un invento a sabiendas de que frecuentemente, otros, antes que él, incursionaron tímida o parcialmente en el mismo tema. Más sin embargo, la obra cumple el propósito fundamental por la cual fue escrita, revalidando su carácter práctico y de gran utilidad para el lector.', 'Libro Físico', 'Medical / History', 0, NULL, 37, 'https://books.google.com/books/publisher/content?id=TgT2DwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&imgtk=AFLRE71NoVVbrR_a_HvE0cm0-C17sUcZ27yHxC7Xr0B0qn6trLrciaTvV_GwQuV7yasVTuBjKc8FacKZP624VYQxZtNV8apP5acn_ET7mEW4pyWERXXF50V4fvTY8jVqL2RwXxCxwJ7A&source=gbs_api', 'leyendo', '', 142, 'TgT2DwAAQBAJ', '2015-11-01'),
(168, 'One Piece 1', 'Eiichiro Oda', 'Esta es la gran Era Pirata. Gold Roger, el legendario “Rey de los piratas” ha dejado el “One Piece” - su legendario Tesoro - escondido en una zona del mundo llamada “GRAND LINE” y los piratas más fuertes compiten por hallarlo. Un niño llamado Luffy idolatraba a los piratas, en especial a Shanks, el líder de una tripulación que visitó su villa. Un día, por accidente, Luffy comió una “fruta del diablo” del botín de Shanks. Gracias a esa fruta, su cuerpo se ha vuelto de goma pero nunca podrá nadar. El día que los piratas abandonaron la villa, Shanks le obsequió a Luffy su mas preciada posesión: su sombrero de paja. Diez años han pasado desde ese día y Luffy ha salido al mar buscando convertirse en el nuevo “Rey de los piratas”. ¡Aquí inicia la gran aventura de Luffy!', 'Libro Físico', 'Comics & Graphic Novels / East Asian Style / Manga / General', 0, NULL, 67, 'https://books.google.com/books/publisher/content?id=lO1zDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&imgtk=AFLRE70rD7GyqKu1E_7tSQFGiKyuPi4afrZBNPFY-hGULoDGPqMlzs1vo5DtauTppzDIJa13VCrSnDo2pZ3QjuEj83julIGPlVxZdSKwC2Wxu5e7dJm48p4jVbcXCpE4ol6ZL_k7CC8U&source=gbs_api', 'leyendo', '', 213, 'lO1zDwAAQBAJ', '2018-10-19'),
(169, 'Absolute Batman: Ark M (2026-) #1', 'Scott Snyder, Frank Tieri', 'The origins of the enigmatic Ark M are explored! What terrible secrets lie within its walls, and just who is assigned to protect it from discovery?!', 'Libro Físico', 'Comics & Graphic Novels / Superheroes', 0, NULL, 67, 'https://books.google.com/books/publisher/content?id=GPWiEQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&imgtk=AFLRE717Fe8FdNfeV_ODTTbtpKYKiUcPJSAO8STneQjzbnUQAwSSqw_qY4rRWkvjoS54DDWZrYmHt0bDS7Tc1bTf_Lq8TZuzFu02sNnueJZwX4qV4IPpHS7s-WI1R_Gs_y2b5i-jy9aW&source=gbs_api', 'leyendo', '', 25, 'GPWiEQAAQBAJ', '2026-01-07'),
(170, 'Absolute Wonder Woman - Bd. 1', 'Thompson Kelly', 'DIE HELDIN AUS DER HÖLLE Zeus verbannt die Amazonen aus der Welt und schickt deren letzte Tochter Diana im Kindesalter in die Hölle. In der Obhut der Hexe Circe wächst Diana dort zu einer starken Kriegerin heran und nimmt es mit den Kreaturen der Unterwelt auf. Als jedoch die Welt der Menschen von gigantischen Monstern angegriffen wird, stürzt sich die Höllen-Prinzessin auf dem Rücken des magischen Skeletts von Pegasus in die Schlacht, um die übermächtigen Gegner so lange wie möglich aufzuhalten. Die aufsehenerregende Neuinterpretation der größten Comic-Heldin aller Zeiten, genial inszeniert von Kelly Thompson (Black Widow) und Hayden Sherman (Batman – Detective Comics).', 'Libro Físico', 'Comics & Graphic Novels / Superheroes', 0, NULL, 67, 'https://books.google.com/books/publisher/content?id=O3mPEQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&imgtk=AFLRE738ujyyjUMUyO-5SRtz4ufy5rJmYJx9ULtKqo1RitMeJBr0lsj9HbJcx_t7zHh6IeceLunr2eIq01vvUlMwPc7AswQIzNVPMbFjS36HLYUYlR0WHi8V220G0mYCdxdWYAcPPt85&source=gbs_api', 'leyendo', '', 100, 'O3mPEQAAQBAJ', '2025-09-30'),
(171, 'Heavenly Delusion, Volume 7', 'Masakazu Ishiguro', 'After Kiruko met with her old idol, she and Maru embark on what should be a long road trip south. Meanwhile in the Academy, chaos has engulfed  the campus and some of the children are now out on their own!<br>', 'Libro Físico', 'Comics & Graphic Novels / Manga / Science Fiction, Comics & Graphic Novels / Manga / Dystopian, Comics & Graphic Novels / Dystopian', 0, NULL, 67, 'https://books.google.com/books/publisher/content?id=_8MMEQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&imgtk=AFLRE72C3G--EoaxATNW2XXDhfNOdyJIBHGHioyTqxuQDRoIJs67pa2NBPaFoaGLiu8KyWGAdNugp4C5Uh2worB0wqAW7s6xVZicayM7fx8X3w9KYdMYR-mf0PTZ-mEx7rJ5UI1VYxmt&source=gbs_api', 'pendiente', '', 193, '_8MMEQAAQBAJ', '2024-06-25'),
(172, 'The Quintessential Quintuplets', 'Negi Haruba', '<p>       Futaro   Uesugi the private tutor has come down sick after the school trip, but not   even illness can keep him from trying to get the quints to study! As he tries   to get closer to the five girls, he ends up driving a wedge between them   instead. And just when he\'s about to hit rock bottom, Futaro\'s past catches   up to him in a big way?! The drama continues in volume 5.   <br></p>', 'Libro Físico', 'Comics & Graphic Novels / Manga / General', 0, NULL, 67, 'https://books.google.com/books/publisher/content?id=iCVyDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&imgtk=AFLRE70I6tIvPFEu2DgHgBesPh7QFa8YhMRuTlLx7Drwgz2SpohsI8wxZ2x0rIwEvKR-Ic58wbKCypijOR3FcFCPYMbZq94Oe1Wfn42Z66wwm7N9OCixxcrdrSf61JrmVAngv0UAOz5A&source=gbs_api', 'pendiente', '', 192, 'iCVyDwAAQBAJ', '2018-10-23'),
(173, 'Go! Go! Loser Ranger! 9', 'Negi Haruba', '<b>Attention kaiju and sentai fans! From the creator of <i>The Quintessential Quintuplets</i> comes a new \"anti-ranger\" action-comedy that\'ll make you root for the alien invaders! Perfect for fans of <i>Kaiju No. 8</i> and <i>Power Rangers</i>.</b><br> <br> CAN D STRIKE THE FINAL BLOW?<br> <br> The Green Squadron has defeated the boss monster Magatia. In the process, the Green Keeper\'s identity was revealed to be...the mysterious informant Chidori! D has now set his sights on a new target and soon receives an opportunity to assassinate him by teaming up with Suzukiri. However, after tailing Chidori all the way to his home, only to ﬁnd a happy family waiting there, will D be able to maintain his resolve?', 'Libro Físico', 'Comics & Graphic Novels / General, Comics & Graphic Novels / East Asian Style / Manga / General, Comics & Graphic Novels / Science Fiction / General, Comics & Graphic Novels / Superheroes, Comics & Graphic Novels / Supervillains, Photography / General', 0, NULL, 67, 'https://books.google.com/books/content?id=4779zwEACAAJ&printsec=frontcover&img=1&zoom=1&imgtk=AFLRE72eEGVLgy18cdQ8DQDlZ-ZmhnLKo6z5QAkB5sgaRy-PWNtK58Qr0ofdY9QURXUB9vHJDDyXihvvAclH68NYLNUDQj4zC9M6cpG9CuS4HPGS_DdT7RBCW4BE9lEy0uFVZFc7yAa4&source=gbs_api', 'pendiente', '', 192, '4779zwEACAAJ', '2024-03-12'),
(174, 'Mushoku Tensei: Jobless Reincarnation Vol. 18', 'Rifujin na Magonote, Yuka Fujikawa', 'Rudeus is enjoying every moment of his newlywed life with his beloved wife Sylphie. However, there is one other person at the University who remembers life on Earth--Nanahoshi. While Rudeus has much to love in his new world, Nanahoshi desperately wants to go back home. She\'s designed a huge magic circle meant to bridge the gap between worlds, but when the experiment goes wrong, it creates a dire crisis of confidence that only Rudeus can set to rights.', 'Libro Físico', 'Comics & Graphic Novels / Fantasy, Comics & Graphic Novels / Action & Adventure', 0, NULL, 67, 'https://books.google.com/books/publisher/content?id=Gu_4EAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&imgtk=AFLRE70YVgxBcx2HLn0212w8N2OAsfUqGHHq4mwl33fs-6qOOvhtl14DS1GDYFObl_vRnHOmxtLYinmLZ5rw7HXchAgrrZuHtIggAlEJbhVhSJhWXPjp79Jio24g8t_o9Wqu9-rBXOGX&source=gbs_api', 'pendiente', '', 168, 'Gu_4EAAAQBAJ', '2024-03-05'),
(175, 'Vinland Saga 10', 'Makoto Yukimura', 'Descripción no disponible', 'Libro Físico', 'Comics & Graphic Novels / East Asian Style / Manga / General', 0, NULL, 67, 'https://books.google.com/books/content?id=xBLOngEACAAJ&printsec=frontcover&img=1&zoom=1&imgtk=AFLRE71M-w8sakl1E3k9gXOndkGd9mpShiIUqoaZFPpSIhFUrsAwmQN7_E-NtAOJiIlHDcPh64eQrWM6tnXt40ICmz2qwuO71Kon3flGmM-ZR5UVDww--W5Jo1kOmgTGPUUCYXx-fLZg&source=gbs_api', 'leyendo', '', 219, 'xBLOngEACAAJ', '2014'),
(177, 'Muerte en el Nilo. Edición Planeta Lector', 'Agatha Christie', '<p> <b>Un célebre caso que pone a prueba la extrema lucidez de HÉRCULES POIROT.</b> </p> <p>Aislados en un crucero en medio del río, la tensión entre los pasajeros va en aumento cuando un triángulo amoroso se convierte en el centro de interés de a bordo. Especialmente cuando el amor pasa a ser letal... <br> <br> «La coartada más ingeniosa que se pueda llegar a imaginar». The Sunday Times <br> «El trabajo de descripción hace que el Nilo cobre vida». The Observer</p>', 'Libro Físico', 'Fiction / Mystery & Detective / General', 0, NULL, 23, 'https://books.google.com/books/publisher/content?id=3czxEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&imgtk=AFLRE70yal09uqtphUEi82g-UltwdKkrbdGlGVnfqB2CV3ignB260Dk-5jrv0LEhNypDemylDl2KGpxmMcU23KmLZcSwAh49glbH6fwTmOBJXB7qtPRwsGUiBs0EMmuHyyKexUGQqNn5&source=gbs_api', 'pendiente', '', 352, '3czxEAAAQBAJ', '2024-02-01'),
(178, 'El aliento de los Dioses', 'Brandon Sanderson', '<p> <b> <i>El aliento de los dioses</i> o <i>Warbreaker</i>, segunda novela de Brandon Sanderson, es una <i>rara avis</i> en la fantasía épica: una narración completa en un único volumen, con toda la imaginación, la aventura, la magia y los entrañables personajes a los que este autor, destinado a heredar el trono de todo un género, nos tiene acostumbrados.</b> </p> <p>Hace años, el monarca de Idris firmó un tratado con el reino de Hallandren según el cual el rey Dedelin enviaría a su hija mayor, Vivenna, para casarse con Susebron, el rey-dios de Hallabdren. Vivenna ha sido adiestrada durante toda su vida para ser una novia adecuada para Susebron y así cumplir con su deber y ayudar a forjar una paz estable entre los dos reinos. Ese era el plan, pero el monarca de Idris envía a su hija Siri, desobediente e independiente, en lugar de Vivenna.</p> <p>Mientras intenta encontrar su lugar en la corte de Susebron, Siri descubre la verdad oculta sobre el rey-dios. En Idris, Vivenna se siente intranquila y teme que su hermana no esté preparada para esa nueva vida, por lo que decide viajar a Hallandren. Allí se reúne con la gente de Idris que trabaja en la capital, Telir, y comienza una nueva vida de espionaje y sabotaje. <b>El plan de Vivenna es rescatar a Siri, aunque tal vez esta ni necesite ni desee ser salvada</b>.</p> <p> <b>Reseñas:</b> <br> «Brandon Sanderson es una leyenda.» <br> Alexelcapo, @EvilAFM</p> <p>«Sanderson no es solo un gran y prolífico autor; es también alguien que, amando la fantasía, sabe que debe ser renovada y que debe ser repensada para encarar con éxito el siglo XXI.» <br> Miquel Barceló, autor de <i>Ciencia ficción. Nueva guía de lectura</i> </p> <p>«Brandon Sanderson es una bomba a punto de estallar.» <br> Ernest Alós, <i>El Periódico de Catalunya</i> </p>', 'Libro Físico', 'Fiction / Fantasy / General', 0, NULL, 81, 'https://books.google.com/books/publisher/content?id=y584AwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&imgtk=AFLRE73i3-Tohlcu4y-AXyLlpahaPo0gNo0ZUtgNwQuGbkZHOX2C0GdTGTHV9H4OUZ0xq4T4IVLqRDF3fZuSa0kF_rGsstVbyWRpqjFfTGLPlfLXHJIeIV06SknTB0mRFGDa-Lj7HfEv&source=gbs_api', 'leyendo', '', 720, 'y584AwAAQBAJ', '2012-02-24'),
(179, 'Nacidos de la Bruma / Mistborn', 'Brandon Sanderson', '<b>Mistborn es la saga que ha convertido a Brandon Sanderson en el gran autor de fantasía del siglo XXI. Más de diez millones de ejemplares vendidos en todo el mundo.<br></b><br> «Una de las mejores obras de fantasía jamás escrita.» - <b><i>Forbes<br></i></b><br> <b>Las brumas gobiernan la noche. El lord Legislador domina el mundo.<br></b><br> En otros tiempos, un héroe se alzó para salvar la humanidad. Fracasó.<br> Desde entonces, el mundo es un erial de ceniza y niebla gobernado por un emperador inmortal conocido como el lord Legislador.<br> <br> Pero la esperanza perdura. Una nueva revuelta cobra forma cimentándose en la treta definitiva: la astucia de un brillante genio del crimen y la determinación de una heroína insólita, una joven ladrona callejera que deberá aprender a controlar el poder de los nacidos de la bruma.<br> <br> <b>ENGLISH DESCRIPTION</b><br> <br> <b>Now with over 10 million copies sold, The Mistborn Series has the thrills of a heist story, the twistiness of political intrigue, and the epic scale of a landmark fantasy saga.</b><br> <br> Once, a hero arose to save the world. He failed.<br> <br> Ever since, the world has been a wasteland of ash and mist controlled by the immortal emperor known as the Lord Ruler.<br> <br> But hope survives. A new uprising is forming, one built around the ultimate caper, the cunning of a brilliant criminal mastermind, and the determination of an unlikely heroine: a street urchin who must learn to master the power of a Mistborn.', 'Libro Físico', 'Comics & Graphic Novels / Adaptations, Fiction / Fantasy / Epic, Fiction / Fantasy / Action & Adventure', 0, NULL, 23, 'https://books.google.com/books/content?id=WnJg0QEACAAJ&printsec=frontcover&img=1&zoom=1&imgtk=AFLRE70NhoAi3p3nhV8vlqbbbZVf0itRuiNj3eHLwUJCnOStYbnhOmcLMzDKa5F5PXNEgO6Mrdb6x7-_0___yLVJdyI25PprbnMqxbDfChg2IDCmijCjJDt7TqzkAqW_x-QqJvczjisv&source=gbs_api', 'pendiente', '', 680, 'WnJg0QEACAAJ', '2025-10-21'),
(180, 'Berserk Deluxe Volume 1', 'Kentaro Miura, Jason DeAngelis', '<b>A stunning deluxe edition collecting volumes 1–3 of the <i>New York Times </i>bestselling adult fantasy horror manga—now presented in the original oversized serialization format!<br><br>Experience <i>Berserk</i> as never before in this collector’s item featuring a leatherette hardcover, red foiling, a ribbon bookmark, and larger-than-life art.</b><br><br><i>Have you got the Guts?</i> Kentaro Miura\'s <i>Berserk</i> has outraged, horrified, and delighted manga and anime fanatics since 1989, creating an international legion of hardcore devotees and inspiring a plethora of TV series, feature films, and video games.<br><br>Now the badass champion of adult fantasy manga is presented as it was originally intended—in an oversized serialization format! This high-quality deluxe edition includes:<br><br><ul><li><i>Berserk</i> Volumes 1–3</li><li>7\" x 10\" leatherette hardcover and binding</li><li>Red foiling details and ribbon bookmark</li><li>Oversized art by Kentaro Miura</li></ul><br>With nearly 700 pages, this is the ultimate collector’s item for new and longtime fans. Complete your manga set of <i>Berserk Deluxe Editions</i> and immerse yourself in the <i>Berserk</i> universe as never before. <i>No Guts, no glory!</i><br><br><b>For mature audiences.</b>', 'Libro Físico', 'Comics & Graphic Novels / East Asian Style / Manga / General, Comics & Graphic Novels / Fantasy / Dark Fantasy, Comics & Graphic Novels / Horror', 0, NULL, 87, 'https://books.google.com/books/publisher/content?id=bLmHDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&imgtk=AFLRE73MtE6cpOLCFs9rLCO9s-eB9dga2S2X3xVpFCq4pqy96LByqksmaY9apygdtB4MaEEEvDtTzYug3Olp7bLSZxWAE9HtsjxBiYlr0Ua7GrzEVLpbGqPcLFssj6UG3J7A-6LUG-mT&source=gbs_api', 'leyendo', '', 696, 'bLmHDwAAQBAJ', '2019-03-26'),
(181, 'El aliento de los Dioses', 'Brandon Sanderson', 'Descripción no disponible', 'paperback', 'No disponible', 0, NULL, 23, 'https://covers.openlibrary.org/b/id/13534599-L.jpg', 'leido', '/works/OL34786153W', 720, '', 'Jun 15, 2016'),
(182, 'El Pozo de la Ascensión', 'Brandon Sanderson', 'Descripción no disponible', 'hardcover', 'No disponible', 0, 0, 89, 'https://covers.openlibrary.org/b/id/13540548-L.jpg', 'leyendo', '/works/OL34790185W', 784, '', 'Sep 30, 2021'),
(185, 'Desafiante (Escuadrón 4)', 'Brandon Sanderson', '<p> <b>La última entrega de la saga Escuadrón: Una chica viajará más allá de las estrellas para salvar la destrucción del mundo.</b> </p> <p>Spensa ha salido de la ninguna-parte, pero lo que vio en el espacio la ha cambiado para siempre. Se enfrentó a los zapadores y por fin obtuvo respuestas a las preguntas que se hacía sobre sus propios y extraños dones citónicos. Pero la Supremacía no ha desistido en su lucha por el dominio galáctico mientras ella no estaba. El equipo de Spensa, el Escuadrón Cielo, logró resistir ante Winzik y hasta sumar aliados a su causa, pero es cuestión de tiempo que la humanidad y el resto de la galaxia caigan. Derrotar a sus enemigos pondrá a prueba todo el conocimiento que Spensa reunió en la ninguna-parte. En este libro final de la saga, la humanidad se liberará o caerá para siempre.</p>', 'Libro Físico', 'Young Adult Fiction / Science Fiction / General, Young Adult Fiction / Science Fiction / Alien Contact', 0, NULL, 23, 'https://books.google.com/books/publisher/content?id=uUDYEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&imgtk=AFLRE70dz_hJDSEBQYWqsSn-WkejHc2c2oUjr1LE-w9BbQMYjb6bjNxvKMUxOx5J03eGIT82Kwk0NE5kqwU4zeRZKg8COWZ1U-jzW6-ZVP8yU8hQt7SWoJV4QWzfga460zomN9BIrgJZ&source=gbs_api', 'leido', '', 464, 'uUDYEAAAQBAJ', '2023-11-23'),
(186, 'Coraline', 'Neil Gaiman', '<p> <b>Acompaña a Coraline y déjate transportar al mundo de fantasía y terror creado por el premiado autor Neil Gaiman.</b> </p> <p>«Damas y caballeros, niñas y niños, pónganse en pie y aplaudan: <i>Coraline</i> es una obra maestra.» <br> <b>Philip Pullman, </b> <i> <b>The Guardian</b> </i> </p> <p>Al día siguiente de mudarse de casa, Coraline explora las catorce puertas de su nuevo hogar. Trece se pueden abrir con normalidad, pero la decimocuarta está cerrada y tapiada. Cuando por fin consigue abrirla, Coraline se encuentra con un pasadizo secreto que la conduce a otra casa tan parecida a la suya que resulta escalofriante.</p> <p>Sin embargo, hay ciertas diferencias que llaman su atención: la comida es más rica, los juguetes son tan desconocidos como maravillosos y, sobre todo, hay otra madre y otro padre que quieren que Coraline se quede con ellos, se convierta en su hija y no se marche nunca. Pronto Coraline se da cuenta de que, tras los espejos, hay otros niños que han caído en la trampa. Son como almas perdidas, y ahora ella es su única esperanza de salvación. Pero para rescatarlos tendrá también que recuperar a sus verdaderos padres, y cumplir así el desafío que le permitirá volver a su vida anterior.</p> <p> <b>Reseñas:</b> <br> «Este libro te producirá escalofríos y el miedo se te colará por los zapatos. Posee el delicado toque de terror de los mejores cuentos de hadas y es una obra maestra. Después de leerlo, no volverás a mirar un botón como antes.» <br> Terry Pratchett</p> <p>«Delicado y extraordinario, se lee como un cruce de <i>Alicia en el país de las maravillas</i> y Stephen King.» <br> <i>Independent on Sunday</i> </p> <p>«Una fantasía magnífica y siniestra; Gaiman muestra un gran conocimiento de los temores de los niños y de su capacidad para superarlos.» <br> <i>Kirkus Reviews</i> </p> <p>«Un libro maravillosamente extraño y espeluznante [...]. Neil Gaiman es demasiado sutil para aludir a lo sobrenatural, es mucho más misterioso. Los peligros son reales y parte de la riqueza de esta historia se encuentra en el hecho de que ofrece muchos significados sin imponer ninguno [...].» <br> Philip Pullman, <i>The Guardian</i> <br> </p> <p>«Gaiman logra tejer una apasionante y adictiva narración, a caballo entre los mitos de los cuentos de hadas infantiles y el suspense propio de un filme de terror. [...] Tras su lectura no volveremos a mirar los botones de la misma manera y cada vez que tengamos que abrir una puerta nos lo pensaremos dos veces.» <br> Sandra Pérez, <i>ABC</i> </p> <p>«Coraline es una digna heredera de las grandes heroínas de la literatura infantil, pero también lo es de las historias góticas de Poe, Lovecraft, etc. Gaiman sabe inventar ambientes y recrear la atmósfera necesaria para arañar e, incluso en ocasiones, hacer estremecerse al lector.» <br> Pep Molist, Quadern, <i> El País</i> </p>', 'Libro Físico', 'Juvenile Fiction / Horror, Juvenile Fiction / Paranormal, Occult & Supernatural', 0, NULL, 23, 'https://books.google.com/books/publisher/content?id=Qu7wDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&imgtk=AFLRE71fYtaZK0-u2Wac6DUBVZbr2gSsZzzt2PV3am5t8Ie9Q5NU8m22loq6rf8uf731moM8QQpUxRjfETVPoEkBwos6nulTpKZDwgFeB04bPwcAgabGY0DMaeTO9Px-G-oVecomgtMN&source=gbs_api', 'leido', '', 160, 'Qu7wDwAAQBAJ', '2020-07-16'),
(187, 'Así es la puta vida', 'Jordi Wild', '<p> <b>El esperado libro de Jordi Wild, uno de los youtubers más populares de España y creador de</b> <i> <b> The Wild Project</b> </i> <b>, el pódcast más escuchado.</b> </p> <p> <b>Ni eres el centro del universo ni todos tus sueños</b> <b>van a cumplirse. Olvídate de las chorradas de los</b> <b>libros de autoayuda y de los gurús baratos que intentan</b> <b>hacerte creer que «si quieres, puedes»; de los</b> <i> <b>crypto bros</b> </i> <b> que te harán millonario sin trabajar y</b> <b>de los que te dicen que seas tu propio jefe mientras</b> <b>se graban en la piscina de la casa de sus padres.</b> </p> <p>Aquí no encontrarás recetas mágicas ni los cinco pasos que tienes que seguir para SER FELIZ. Eso se lo dejo a los que se quieren aprovechar de ti.</p> <p>En este libro te voy a contar lo que para mí es la vida de verdad, sin edulcorantes ni azúcares añadidos; la jodida (y maravillosa) lucha que tienes que librar cada día para poder disfrutar y realizarte. La vida te dará una buena somanta de hostias, eso es inevitable, pero de ti depende levantarte y seguir guerreando. Vale la pena, te lo aseguro.</p> <p> <p> <b>ASÍ ES LA PUTA VIDA.</b> <b>ESPERO QUE ESTÉS PREPARADO</b> <b>PARA ACEPTARLO.</b> </p>', 'Libro Físico', 'Psychology / General, Psychology / Essays', 0, NULL, 23, 'https://books.google.com/books/publisher/content?id=72-JEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&imgtk=AFLRE71r3ZAcNoHk7Mf0meDtrob8KE6hdH5trrXWRgLe2qZf826KIKI03GP1kjUfRZKB6MBQTJWSa7B_1zJHlaJlFOMG_AXcrhe7JXOmGLC37ogtryETNOTBN-VX1aG6CsUpAVfur4od&source=gbs_api', 'leido', '', 208, '72-JEAAAQBAJ', '2022-11-03'),
(188, 'Diez negritos', 'Agatha Christie', 'Diez negritos es una trepidante obra de intriga en la que diez personas sin relación alguna entre sí son invitadas a la lujosa mansión en un islote de la costa inglesa del señor Owen, al que ninguno de sus invitados conoce. Tras la primera cena juntos, los diez comensales son acusados a través de un magnetófono de haber cometido un crimen. Una vieja canción infantil contiene el misterio de una tremenda pesadilla.', 'Libro Físico', 'Fiction / Thrillers / Suspense, Fiction / Mystery & Detective / General', 0, NULL, 23, 'https://books.google.com/books/publisher/content?id=QXqyEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&imgtk=AFLRE72QBJi44gZo7SCQXAgnxt70Clc_xCuvxDD8FQ4ZHS6F9kk32mBVJaNsEAYbRE9Gc8qreHEVNistb2CVoc_4MKP6JAij5dgdsD2MQWT25XS8MSiPEJn-XRAqwQTqHTpia2uQgsyG&source=gbs_api', 'leido', '', 180, 'QXqyEAAAQBAJ', '2023-02-16'),
(189, 'Cinco Cerditos / Five Little Pigs', 'Agatha Christie', '<p><b>Una joven acude al detective Hercules Poirot para que resuelva un crimen cometido dieciséis años atrás, ¿logrará resolver este misterio?</b></p><p>Caroline Crale es condenada por el asesinato de su esposo, el pintor Amyas Crale, dieciséis años atrás. Ahora, la hija de ambos, Carla, está dispuesta a remover cielo y tierra para descubrir la verdadera identidad del asesino de su padre y limpiar así la memoria de su desdichada madre.</p><p>Con escasas pruebas, la tarea de Poirot se complica cuando comprueba que sus cinco sospechosos tienen, aparentemente, sólidas coartadas. Pero ¿quién será capaz de mantenerse firme ante la inquisitiva perspicacia de tan audaz investigador? Otro caso sorprendente de Poirot.</p><b> <p>ENGLISH DESCRIPTION</b><p></p><p><b>In this exclusive authorized edition from the Queen of Mystery, beloved detective Hercule Poirot races to solve a case from out of the past.</b></p><p></p> <p>Beautiful Caroline Crale was convicted of poisoning her husband, but just like the nursery rhyme, there were five other \"little pigs\" who could have done it: Philip Blake (the stockbroker), who went to market; Meredith Blake (the amateur herbalist), who stayed at home; Elsa Greer (the three-time divorcée), who had her roast beef; Cecilia Williams (the devoted governess), who had none; and Angela Warren (the disfigured sister), who cried all the way home.<p></p> <p>Sixteen years later, Caroline\'s daughter is determined to prove her mother\'s innocence, and Poirot just can\'t get that nursery rhyme out of his mind.<p></p> <p><p></p>', 'Libro Físico', 'Fiction / Classics, Fiction / Mystery & Detective / Private Investigators, Fiction / Thrillers / Crime, Fiction / Noir, Fiction / World Literature / England / 20th Century', 0, NULL, 23, 'https://books.google.com/books/content?id=gNlEzwEACAAJ&printsec=frontcover&img=1&zoom=1&imgtk=AFLRE73xaFr8qIv67GJ1F2CV5_5eicZ-pqAICz6gL6dn0VbX_KyYvqYat9cTeHOyiqmbqqKTaoKE28mSDCRfA1MLtzhCdq_W-2baXMP5G5PFxfQJMN8suOZ9WhhkrpRDLst0Muq6PURZ&source=gbs_api', 'leido', '', 208, 'gNlEzwEACAAJ', '2022-08-23'),
(190, 'El principio del terror', 'Jaime Muñoz Vargas', 'Descripción no disponible', 'Libro Físico', 'Music / History & Criticism', 0, NULL, 23, 'https://books.google.com/books/content?id=iV8eAQAAIAAJ&printsec=frontcover&img=1&zoom=1&imgtk=AFLRE71ktN0ng_A41mRp9ZxU-Rsbo53RetLcxoTAgudaRyV5UsEykbodCW6UiI8pAASY1NvdEEm10uV0ix0dG5bwNH80N5czdG0DzV4gmBDwwNg2kQ9eiOegnXt1ZIi31Y0kW5x8xqet&source=gbs_api', 'leido', '', 114, 'iV8eAQAAIAAJ', '1999'),
(191, 'Un vampiro en Maracaibo', 'Norberto José Olivar', 'Descripción no disponible', 'Libro Físico', NULL, 0, NULL, 23, 'https://books.google.com/books/content?id=ljpKAAAAYAAJ&printsec=frontcover&img=1&zoom=1&imgtk=AFLRE73kdcRgqVO6furle5TKthFX3m2TDStDVN_zCkzVm2uttdayEpUuWRhBPyiDaNW5FVwBE3INMGR3UqqKuwh6kRTEqUhYSn2hwj1fgvQHgDl6TEyc1lHOGE6p0ihYr5_56bNzkKYl&source=gbs_api', 'leido', '', 256, 'ljpKAAAAYAAJ', '2008'),
(192, 'Nacidos de la Bruma / Mistborn', 'Brandon Sanderson', '<b>Mistborn es la saga que ha convertido a Brandon Sanderson en el gran autor de fantasía del siglo XXI. Más de diez millones de ejemplares vendidos en todo el mundo.<br></b><br> «Una de las mejores obras de fantasía jamás escrita.» - <b><i>Forbes<br></i></b><br> <b>Las brumas gobiernan la noche. El lord Legislador domina el mundo.<br></b><br> En otros tiempos, un héroe se alzó para salvar la humanidad. Fracasó.<br> Desde entonces, el mundo es un erial de ceniza y niebla gobernado por un emperador inmortal conocido como el lord Legislador.<br> <br> Pero la esperanza perdura. Una nueva revuelta cobra forma cimentándose en la treta definitiva: la astucia de un brillante genio del crimen y la determinación de una heroína insólita, una joven ladrona callejera que deberá aprender a controlar el poder de los nacidos de la bruma.<br> <br> <b>ENGLISH DESCRIPTION</b><br> <br> <b>Now with over 10 million copies sold, The Mistborn Series has the thrills of a heist story, the twistiness of political intrigue, and the epic scale of a landmark fantasy saga.</b><br> <br> Once, a hero arose to save the world. He failed.<br> <br> Ever since, the world has been a wasteland of ash and mist controlled by the immortal emperor known as the Lord Ruler.<br> <br> But hope survives. A new uprising is forming, one built around the ultimate caper, the cunning of a brilliant criminal mastermind, and the determination of an unlikely heroine: a street urchin who must learn to master the power of a Mistborn.', 'Libro Físico', 'Comics & Graphic Novels / Adaptations, Fiction / Fantasy / Epic, Fiction / Fantasy / Action & Adventure', 0, NULL, 45, 'https://books.google.com/books/content?id=WnJg0QEACAAJ&printsec=frontcover&img=1&zoom=1&imgtk=AFLRE70NhoAi3p3nhV8vlqbbbZVf0itRuiNj3eHLwUJCnOStYbnhOmcLMzDKa5F5PXNEgO6Mrdb6x7-_0___yLVJdyI25PprbnMqxbDfChg2IDCmijCjJDt7TqzkAqW_x-QqJvczjisv&source=gbs_api', 'leyendo', '', 680, 'WnJg0QEACAAJ', '2025-10-21'),
(193, 'Cinco Cerditos / Five Little Pigs', 'Agatha Christie', '<p><b>Una joven acude al detective Hercules Poirot para que resuelva un crimen cometido dieciséis años atrás, ¿logrará resolver este misterio?</b></p><p>Caroline Crale es condenada por el asesinato de su esposo, el pintor Amyas Crale, dieciséis años atrás. Ahora, la hija de ambos, Carla, está dispuesta a remover cielo y tierra para descubrir la verdadera identidad del asesino de su padre y limpiar así la memoria de su desdichada madre.</p><p>Con escasas pruebas, la tarea de Poirot se complica cuando comprueba que sus cinco sospechosos tienen, aparentemente, sólidas coartadas. Pero ¿quién será capaz de mantenerse firme ante la inquisitiva perspicacia de tan audaz investigador? Otro caso sorprendente de Poirot.</p><b> <p>ENGLISH DESCRIPTION</b><p></p><p><b>In this exclusive authorized edition from the Queen of Mystery, beloved detective Hercule Poirot races to solve a case from out of the past.</b></p><p></p> <p>Beautiful Caroline Crale was convicted of poisoning her husband, but just like the nursery rhyme, there were five other \"little pigs\" who could have done it: Philip Blake (the stockbroker), who went to market; Meredith Blake (the amateur herbalist), who stayed at home; Elsa Greer (the three-time divorcée), who had her roast beef; Cecilia Williams (the devoted governess), who had none; and Angela Warren (the disfigured sister), who cried all the way home.<p></p> <p>Sixteen years later, Caroline\'s daughter is determined to prove her mother\'s innocence, and Poirot just can\'t get that nursery rhyme out of his mind.<p></p> <p><p></p>', 'Libro Físico', 'Fiction / Classics, Fiction / Mystery & Detective / Private Investigators, Fiction / Thrillers / Crime, Fiction / Noir, Fiction / World Literature / England / 20th Century', 0, NULL, 45, 'https://books.google.com/books/content?id=gNlEzwEACAAJ&printsec=frontcover&img=1&zoom=1&imgtk=AFLRE73xaFr8qIv67GJ1F2CV5_5eicZ-pqAICz6gL6dn0VbX_KyYvqYat9cTeHOyiqmbqqKTaoKE28mSDCRfA1MLtzhCdq_W-2baXMP5G5PFxfQJMN8suOZ9WhhkrpRDLst0Muq6PURZ&source=gbs_api', 'leyendo', '', 208, 'gNlEzwEACAAJ', '2022-08-23'),
(194, 'Nacidos de la bruma (Trilogía Original Mistborn: edición ilustrada 1)', 'Brandon Sanderson', '<p> <b>Nueva edición de <i>El Imperio Final</i>. El primer volumen de «Nacidos de la Bruma (Mistborn)», con 8 ilustraciones a color.</b> </p> <p> <p> <b>Brandon Sanderson es el gran renovador de la fantasía del siglo XXI, con veinte millones de lectores en todo el mundo.</b> </p> <p>La saga Nacidos de la Bruma (Mistborn) es una obra imprescindible del Cosmere, el universo destinado a dar forma a la serie más extensa y fascinante jamás escrita en el ámbito de la fantasía épica.</p> <p>Durante mil años han caído cenizas del cielo. Durante mil años nada ha florecido. Durante mil años los skaa han sido esclavizados y viven en la miseria, sumidos en un miedo inevitable. Durante mil años el Lord Legislador ha reinado con poder absoluto, dominando gracias al terror, a sus poderes y a su inmortalidad, ayudado por «obligadores» e «inquisidores», junto a la poderosa magia de la alomancia.</p> <p>Pero los nobles a menudo han tenido trato sexual con jóvenes skaa y, aunque la ley lo prohíbe, algunos de sus bastardos han sobrevivido y heredado los poderes alománticos: son los «Nacidos de la Bruma» (Mistborn).</p> <p>Ahora, Kelsier, el «superviviente», el único que ha logrado huir de los Pozos de Hathsin, ha encontrado a Vin, una pobre chica skaa con mucha suerte... Tal vez los dos, con el mejor equipo criminal jamás reunido, unidos a la rebelión que los skaa intentan desde hace mil años, logren cambiar el mundo y acabar con la atroz mano de hierro del Lord Legislador.</p>', 'Libro Físico', 'Fiction / Fantasy / Epic', 0, NULL, 45, 'https://books.google.com/books/publisher/content?id=2gk0EAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&imgtk=AFLRE71FwDOXUDF9epiZQF5JU4CJJVZz7_DQJY22lgoriuhE5niYsfl_ljlXi7Ib22Tq5UlmMtjDFpjrGYCaEwdyenKr5YqeotfKlmG-cXXZM2CZxPAB3HIVfMUdLDrib8hZuppVqUow&source=gbs_api', 'leido', '', 672, '2gk0EAAAQBAJ', '2021-07-08'),
(195, 'El Parque Jurásico', 'Michael Crichton', 'Descripción no disponible', 'Libro Físico', NULL, 0, NULL, 45, 'https://books.google.com/books/content?id=bPgXJwuGZpYC&printsec=frontcover&img=1&zoom=1&imgtk=AFLRE70hTDpUQXaSXANHO7yuHCHS6uCUHU-45D6QJuEF861OhZ3erMUP47SGDQzRBzO2T5nYg2FvLtzUIhVSYjge5fs8vV_uJvzJeI9fHV6huxUXcvu-vmwQ_yv4llZtUXgNeljH5Bmq&source=gbs_api', 'leido', '', 443, 'bPgXJwuGZpYC', '1991'),
(196, 'Un vampiro en Maracaibo', 'Norberto José Olivar', 'Descripción no disponible', 'Libro Físico', NULL, 0, NULL, 45, 'https://books.google.com/books/content?id=ljpKAAAAYAAJ&printsec=frontcover&img=1&zoom=1&imgtk=AFLRE73kdcRgqVO6furle5TKthFX3m2TDStDVN_zCkzVm2uttdayEpUuWRhBPyiDaNW5FVwBE3INMGR3UqqKuwh6kRTEqUhYSn2hwj1fgvQHgDl6TEyc1lHOGE6p0ihYr5_56bNzkKYl&source=gbs_api', 'leido', '', 256, 'ljpKAAAAYAAJ', '2008'),
(197, 'Harry Potter y la piedra filosofal', 'J. K. Rowling', 'For use in schools and libraries only. Rescued from the outrageous neglect of his aunt and uncle, a young boy with a great destiny proves his worth while attending Hogwarts School for Witchcraft and Wizardry.', 'Libro Físico', 'Juvenile Fiction / Family / Orphans & Foster Homes, Juvenile Fiction / Humorous Stories, Juvenile Fiction / School & Education, Juvenile Fiction / Fantasy & Magic, Juvenile Fiction / Science Fiction / General', 0, NULL, 45, 'https://books.google.com/books/content?id=4RENAQAAMAAJ&printsec=frontcover&img=1&zoom=1&imgtk=AFLRE71S-1Pw6j3XGPGI-WHktyMvzJ5MwokOZXO2RyfpUb9P336c-pjb5HM0M1uQrWvL9D8VYchIn38wxZqMREDal7j2tRoLN9dRnZoT8PwjbKkyxy_q9Z1KJb4asBXZTEdLuyoPQQ8O&source=gbs_api', 'leido', '', 254, '4RENAQAAMAAJ', '2001'),
(198, 'Chainsaw Man T03', 'Tatsuki Fujimoto', 'Un mystérieux démon a emprisonné nos héros et exigent d\'eux qu\'ils tuent Denji pour les libérer ! Acculés, les membres de la 4e section spéciale Anti-Démons se divisent. Mais en dépit des conditions extrêmes, Denji, plus motivé que jamais par le baiser qui récompensera le vainqueur, imagine une stratégie infernale pour s\'en sortir ! Dans la bataille épique qui éclate, le pauvre Denji est à la fois l\'acteur et le trophée...', 'Libro Físico', 'Comics & Graphic Novels / East Asian Style / Manga / General, Comics & Graphic Novels / Manga / For boys', 0, NULL, 90, 'https://books.google.com/books/publisher/content?id=WzbpDwAAQBAJ&printsec=frontcover&img=1&zoom=1&imgtk=AFLRE70jwb1S8k5i3wwPrZWeu1rVH70RZFBYrZSytRsnBz4We276y0HBd1EHbvRZnGqAe_7MUmBKOJgtrVdjxUf82wg4TWVuKUL17h7xNxYcxczP8z3LumWVUs9g0VLaaMrfZz3mDYjx&source=gbs_api', 'leyendo', '', 192, 'WzbpDwAAQBAJ', '2020-07-01'),
(199, 'Jujutsu Kaisen, Vol. 4', 'Gege Akutami', '<p>While investigating a strange set of mysterious deaths, Itadori meets Junpei, a troubled kid who is often bullied at school. However, Junpei is also befriended by the culprit behind the bloody incident—Mahito, a mischievous cursed spirit! Mahito sets in motion a devious plan involving Junpei, hoping to ensnare Itadori as well.</p>', 'Libro Físico', 'Comics & Graphic Novels / East Asian Style / Manga / General, Comics & Graphic Novels / Fantasy / General, Comics & Graphic Novels / Occult & Supernatural', 0, NULL, 90, 'https://books.google.com/books/publisher/content?id=b93lDwAAQBAJ&printsec=frontcover&img=1&zoom=1&imgtk=AFLRE72uHJiW88B2JoJQOEI7IQT2BvusfuKYTRm5g5zEKGuY9vBqg_cFZ45lBrk1BP7eO-Rw5s0ovDlv8VhcosM4U3A7fcGNm7vYFddbI7B-v4JIPiz2eG3hri643Meav5HeyXYN2xpY&source=gbs_api', 'leyendo', '', 199, 'b93lDwAAQBAJ', '2020-06-02'),
(202, 'Cosas pequeñas como esas', 'Claire Keegan', 'Qué quietud había ahí arriba, pero ¿por qué nunca estaba en paz? El día aún no despuntaba, y Furlong miró hacia el río oscuro y brillante cuya superficie reflejaba partes equivalentes del pueblo iluminado. Eran tantas las cosas que se veían mejor, cuando no estaban tan cerca. No pudo decir cuál prefería; si la vista del pueblo o su reflejo en el agua. Invierno de 1985 en un pequeño pueblo irlandés. Bill Furlong es un hombre amable y un trabajador infatigable, vende carbón y madera. Su única preocupación es que a su esposa y a sus cinco hijas no les falte nada. Lleva una vida tranquila y rutinaria, hasta que un día, mientras entrega un pedido en el convento del pueblo, se involucra en una situación que le devuelve otra imagen de su pasado, dejándolo en medio de una encrucijada definitiva: por un lado, seguir su instinto de autopreservación y mirar hacia abajo, por el otro, actuar con coraje y hacer lo correcto, sin importar las consecuencias. Claire Keegan, una de las voces más potentes de la literatura irlandesa contemporánea, se detiene con perspicacia en esas pequeñas cosas que hacen la diferencia y construye una novela de una delicadeza conmovedora. &quot;En Cosas pequeñas como esas, Claire Keegan crea escenas con asombrosa claridad y lucidez. Esta es la historia de lo que sucedió en Irlanda, contado con simpatía y precisión emocional.&quot; Colm Tóibín', 'Libro Físico', 'Literary Criticism / Women Authors, Fiction / General', 0, NULL, 23, 'https://books.google.com/books/publisher/content?id=i91EEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&imgtk=AFLRE70a6uVuU1jXQwMTu7YLeu9tNHx-JsdYz1QAWGyahrBVPsafX_74pBeP_6AzAFJAvT-uW1CS8n2zdMqw7B6Tx9klXytWTdhHto9O75YxmZ2MJTVKVCFMJAU99sz17GTu4R7nbCqy&source=gbs_api', 'leyendo', '', 96, 'i91EEAAAQBAJ', '2021-09-24');
