INSERT INTO `recomendaciones_cache` (`id`, `id_usuario`, `titulo`, `autor`, `descripcion`, `portada`, `paginas`, `generos`, `anio`, `id_google`, `fecha_generacion`, `key`) VALUES
(11, 6, 'Los Juegos del Hambre - Trilogía Los Juegos del Hambre', 'Suzanne Collins', 'Los Juegos del Hambre, una de las sagas más exitosas de todos los tiempos reunida en un bonito estuche. Este pack contiene los tres títulos de la trilogía Los Juegos del Hambre: Los Juegos de Hambre En una oscura versión del futuro próximo, doce chicos y doce chicas se ven obligados a participar en un reality show llamado Los Juegos del Hambre. Solo hay una regla: matar o morir. En llamas Contra todo pronóstico, Katniss Everdeen y Peeta Mellark han sobrevivido a Los Juegos del Hambre. Deberían sentirse aliviados, pero saben que la tensión crece en el Capitolio, que los gobierna a todos. Sinsajo Los supervivientes de Los Juegos del Hambre no están a salvo. Un meticuloso plan se extiende contra el Capitolio... Y este necesita un símbolo, el emblema de la rebelión: el Sinsajo.', 'https://via.placeholder.com/200x300?text=Sin+Portada', 0, 'Juvenile Fiction', '2019-03-07', '89tu0AEACAAJ', '2026-07-08 19:05:11', NULL),
(10, 6, 'Cien años de soledad', 'Gabriel García Márquez', 'Señalada como «catedral gótica del lenguaje», este clásico del siglo XX es el enorme y espléndido tapiz de la saga de la familia Buendía, en la mítica aldea de Macondo. UNO DE LOS 5 LIBROS MÁS IMPORTANTES DE LOS ÚLTIMOS 125 AÑOS SEGÚN THE NEW YORK TIMES Un referente imprescindible de la vida y la narrativa latinoamericana. «Muchos años después, frente al pelotón de fusilamiento, el coronel Aureliano Buendía había de recordar aquella tarde remota en que su padre lo llevó a conocer el hielo. Macondo era entonces una aldea de veinte casas de barro y cañabrava construidas a la orilla de un río de aguas diáfanas que se precipitaban por un lecho de piedras pulidas, blancas y enormes como huevos prehistóricos. El mundo era tan reciente, que muchas cosas carecían de nombre, y para mencionarlas había que señalarlas con el dedo». Con estas palabras empieza la novela ya legendaria en los anales de la literatura universal, una de las aventuras literarias más fascinantes de nuestro siglo. Millones de ejemplares de Cien años de soledad leídos en todas las lenguas y el Premio Nobel de Literatura coronando una obra que se había abierto paso «boca a boca» -como gusta decir al escritor- son la más palpable demostración de que la aventura fabulosa de la familia Buendía-Iguarán, con sus milagros, fantasías, obsesiones, tragedias, incestos, adulterios, rebeldías, descubrimientos y condenas, representaba al mismo tiempo el mito y la historia, la tragedia y el amor del mundo entero. Pablo Neruda dijo... «El Quijote de nuestro tiempo.»', 'http://books.google.com/books/content?id=kmAQCwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 311, 'Fiction', '2015-12-03', 'kmAQCwAAQBAJ', '2026-07-08 19:05:11', NULL),
(9, 6, '1984', 'George Orwell', '75th ANNIVERSARY EDITION “Orwell saw, to his credit, that the act of falsifying reality is only secondarily a way of changing perceptions. It is, above all, a way of asserting power.”—The New Yorker In 1984, London is a grim city in the totalitarian state of Oceania where Big Brother is always watching you and the Thought Police can practically read your mind. Winston Smith is a man in grave danger for the simple reason that his memory still functions. Drawn into a forbidden love affair, Winston finds the courage to join a secret revolutionary organization called The Brotherhood, dedicated to the destruction of the Party. Together with his beloved Julia, he hazards his life in a deadly match against the powers that be. Lionel Trilling said of Orwell’s masterpiece, “1984 is a profound, terrifying, and wholly fascinating book. It is a fantasy of the political future, and like any such fantasy, serves its author as a magnifying device for an examination of the present.” Though the year 1984 now exists in the past, Orwell’s novel remains an urgent call for the individual willing to speak truth to power.', 'http://books.google.com/books/content?id=kotPYEqx7kMC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 309, 'Fiction', '2013-09-03', 'kotPYEqx7kMC', '2026-07-08 19:05:11', NULL),
(24, 22, 'Orgullo y prejuicio', 'Jane Austen', 'Orgullo y prejuicio (Pride and Prejudice), publicada por primera vez el 28 de enero de 1813 como una obra anónima, es la más famosa de las novelas de Jane Austen y una de las primeras comedias románticas en la historia del género. Su primera frase es, además, una de las más famosas en la literatura inglesa: “Es una verdad mundialmente reconocida que un hombre soltero, poseedor de una gran fortuna, necesita una esposa.” Cuando Jane Austen escribió la novela, apenas tenía veinte años, y compartía habitación con su hermana. La primera redacción de la obra data del periodo 1796-1797; inicialmente recibió el título de \"Primeras impresiones\" (First Impressions), pero nunca fue publicado con ese nombre. En 1797 el padre de Jane lo ofreció a un editor, que lo rechazó. Jane Austen revisó la obra en 1809-1810 y de nuevo en 1812, y la ofreció entonces, con el apoyo de su hermano Henry, a otro editor, que había publicado Sentido y sensibilidad el año anterior. Finalmente fue publicada y pronto gozó de gran éxito. Satírica, profunda y mordaz a un tiempo, la obra de Jane Austen nace de la observación de la vida doméstica y de un profundo conocimiento de la condición humana. Orgullo y prejuicio ha fascinado a generaciones de lectores por sus inolvidables personajes y su desopilante retrato de una sociedad, la Inglaterra victoriana y rural, tan contradictoria como absurda. Esta novela, donde Austen relata la historia de las cinco hermanas Bennet y las tribulaciones de sus respectivos amoríos, ha sido llevada al cine en reiteradas ocasiones, se ha versionado en cómic y en musicales, lo que demuestra su actualidad e interés contemporáneos.', 'http://books.google.com/books/content?id=ojyzDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 328, 'Drama', '2016-07-01', 'ojyzDwAAQBAJ', '2026-07-08 19:16:58', NULL),
(25, 22, 'Cien años de soledad', 'Gabriel García Márquez', 'Señalada como «catedral gótica del lenguaje», este clásico del siglo XX es el enorme y espléndido tapiz de la saga de la familia Buendía, en la mítica aldea de Macondo. UNO DE LOS 5 LIBROS MÁS IMPORTANTES DE LOS ÚLTIMOS 125 AÑOS SEGÚN THE NEW YORK TIMES Un referente imprescindible de la vida y la narrativa latinoamericana. «Muchos años después, frente al pelotón de fusilamiento, el coronel Aureliano Buendía había de recordar aquella tarde remota en que su padre lo llevó a conocer el hielo. Macondo era entonces una aldea de veinte casas de barro y cañabrava construidas a la orilla de un río de aguas diáfanas que se precipitaban por un lecho de piedras pulidas, blancas y enormes como huevos prehistóricos. El mundo era tan reciente, que muchas cosas carecían de nombre, y para mencionarlas había que señalarlas con el dedo». Con estas palabras empieza la novela ya legendaria en los anales de la literatura universal, una de las aventuras literarias más fascinantes de nuestro siglo. Millones de ejemplares de Cien años de soledad leídos en todas las lenguas y el Premio Nobel de Literatura coronando una obra que se había abierto paso «boca a boca» -como gusta decir al escritor- son la más palpable demostración de que la aventura fabulosa de la familia Buendía-Iguarán, con sus milagros, fantasías, obsesiones, tragedias, incestos, adulterios, rebeldías, descubrimientos y condenas, representaba al mismo tiempo el mito y la historia, la tragedia y el amor del mundo entero. Pablo Neruda dijo... «El Quijote de nuestro tiempo.»', 'http://books.google.com/books/content?id=kmAQCwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 311, 'Fiction', '2015-12-03', 'kmAQCwAAQBAJ', '2026-07-08 19:16:58', NULL),
(26, 25, 'Orgullo y prejuicio', 'Jane Austen', 'Las novelas de JANE AUSTEN (1775-1817) suelen girar en torno al paso de la juventud a la edad adulta, el consiguiente acceso a la sociedad y el natural corolario de este proceso en el medio en que estas relaciones se desarrollan -el matrimonio-, así como sus consecuencias. ORGULLO Y PREJUICIO se teje alrededor de las relaciones que se establecen entre dos grupos familiares en la Inglaterra rural: por una parte el matrimonio Bennet con sus cinco hijas -entre las que destaca especialmente Elizabeth, despierta y vivaz-, y por otra el rico Charles Bingley y sus dos hermanas, junto con su aún más rico amigo Fitzwilliam Darcy. Marcados en un principio por los prejuicios y los malos entendidos, los vínculos sociales y sentimentales entre los miembros de una y otra parte van madurando y matizándose a lo largo de la novela para acabar alcanzando un buen fin. Otras obras de Jane Austen en esta colección: «Emma» (LB 1784).', 'http://books.google.com/books/content?id=MHvfwAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 448, 'Fiction', '2002', 'MHvfwAEACAAJ', '2026-07-08 22:13:44', NULL),
(27, 25, 'Cien años de soledad', 'Gabriel García Márquez', 'Señalada como «catedral gótica del lenguaje», este clásico del siglo XX es el enorme y espléndido tapiz de la saga de la familia Buendía, en la mítica aldea de Macondo. UNO DE LOS 5 LIBROS MÁS IMPORTANTES DE LOS ÚLTIMOS 125 AÑOS SEGÚN THE NEW YORK TIMES Un referente imprescindible de la vida y la narrativa latinoamericana. «Muchos años después, frente al pelotón de fusilamiento, el coronel Aureliano Buendía había de recordar aquella tarde remota en que su padre lo llevó a conocer el hielo. Macondo era entonces una aldea de veinte casas de barro y cañabrava construidas a la orilla de un río de aguas diáfanas que se precipitaban por un lecho de piedras pulidas, blancas y enormes como huevos prehistóricos. El mundo era tan reciente, que muchas cosas carecían de nombre, y para mencionarlas había que señalarlas con el dedo». Con estas palabras empieza la novela ya legendaria en los anales de la literatura universal, una de las aventuras literarias más fascinantes de nuestro siglo. Millones de ejemplares de Cien años de soledad leídos en todas las lenguas y el Premio Nobel de Literatura coronando una obra que se había abierto paso «boca a boca» -como gusta decir al escritor- son la más palpable demostración de que la aventura fabulosa de la familia Buendía-Iguarán, con sus milagros, fantasías, obsesiones, tragedias, incestos, adulterios, rebeldías, descubrimientos y condenas, representaba al mismo tiempo el mito y la historia, la tragedia y el amor del mundo entero. Pablo Neruda dijo... «El Quijote de nuestro tiempo.»', 'http://books.google.com/books/content?id=kmAQCwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 311, 'Fiction', '2015-12-03', 'kmAQCwAAQBAJ', '2026-07-08 22:13:44', NULL),
(324, 56, 'El Hobbit, o, Historia de una Ida y de una Vuelta', 'J. R. R. Tolkien', 'Bilbo Bolsón es como cualquier hobbit: no mide más de metro y medio, vive pacíficamente en la Comarca, y su máxima aspiración es disfrutar de los placeres sencillos de la vida (comer bien, pasear y charlar con los amigos). Y es que todos ellos son tan vagos como bonachones, por naturaleza, y porque quieren. Pero una soleada mañana, Bilbo recibe la inesperada visita de Gandalf, el mago de larga barba gris y alto sombrero, que cambiará su vida para siempre. Con Gandalf y una pandilla de trece enanos, y con la ayuda de un mapa misterioso, nuestro héroe partirá hacia la Montaña Solitaria a fin de rescatar el valioso tesoro custodiado por Smaug el Dorado, un terrible y enorme dragón. Para eso tendrán que superar muchísimos peligros y toda clase de aventuras que Bilbo jamás hubiera podido ni imaginar y que lo convertirán en el hobbit más famoso del mundo. Lo que Bilbo no sabe es que el anillo que encontró en el camino será el principio de otra gran aventura... la de El Señor de los Anillos. Pero ésa es otra historia, de momento, ¡no te pierdas este fabuloso viaje por la Tierra Media!', 'http://books.google.com/books/content?id=jVixPAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 360, 'Comics & Graphic Novels', '2003-09', 'jVixPAAACAAJ', '2026-07-26 14:57:50', NULL),
(325, 56, '1984', 'George Orwell', '75th ANNIVERSARY EDITION “Orwell saw, to his credit, that the act of falsifying reality is only secondarily a way of changing perceptions. It is, above all, a way of asserting power.”—The New Yorker In 1984, London is a grim city in the totalitarian state of Oceania where Big Brother is always watching you and the Thought Police can practically read your mind. Winston Smith is a man in grave danger for the simple reason that his memory still functions. Drawn into a forbidden love affair, Winston finds the courage to join a secret revolutionary organization called The Brotherhood, dedicated to the destruction of the Party. Together with his beloved Julia, he hazards his life in a deadly match against the powers that be. Lionel Trilling said of Orwell’s masterpiece, “1984 is a profound, terrifying, and wholly fascinating book. It is a fantasy of the political future, and like any such fantasy, serves its author as a magnifying device for an examination of the present.” Though the year 1984 now exists in the past, Orwell’s novel remains an urgent call for the individual willing to speak truth to power.', 'http://books.google.com/books/content?id=kotPYEqx7kMC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 309, 'Fiction', '2013-09-03', 'kotPYEqx7kMC', '2026-07-26 14:57:50', NULL),
