INSERT INTO `recomendaciones_cache` (`id`, `id_usuario`, `titulo`, `autor`, `descripcion`, `portada`, `paginas`, `generos`, `anio`, `id_google`, `fecha_generacion`, `key`) VALUES
(1351, 74, 'El nombre de la rosa', 'Umberto Eco', 'La novela emblemática de Umberto Eco. Una trama apasionante. Una admirable reconstrucción del conflictivo siglo XIV «Umberto Eco cambió nuestra mirada sobre los libros: imprescindibles, pequeños, frágiles, a veces criminales, casi siempre salvadores. Un maestro que nos enseñó a entrelazar la sabiduría y el juego con su estilo sagaz y lúdico, con su asombrosa inventiva y certera lucidez.» Irene Vallejo UNO DE LOS 100 TÍTULOS FUNDAMENTALES DEL SIGLO XX SEGÚN LE MONDE Valiéndose de las características de la novela gótica, la crónica medieval y la novela policíaca, El nombre de la rosa narra las investigaciones detectivescas que realiza el fraile franciscano Guillermo de Baskerville para esclarecer los crímenes cometidos en una abadía benedictina en el año 1327. Le ayudará en su labor el novicio Adso, un joven que se enfrenta por primera vez a las realidades de la vida situadas más allá de las puertas del convento. En esta primera y brillante incursión de Umberto Eco en el mundo de la narrativa, que dio lugar a una manera de concebir la novela histórica, el lector disfrutará de una trama apasionante y una admirable reconstrucción de una época especialmente conflictiva de la historia de Occidente. La crítica ha dicho: «Una lectura obligada, incluso si no estás completamente seguro de entenderlo del todo, o si ni siquiera estás seguro de que sea posible entenderlo del todo». Jorge Coscarón, Esquire «Una genialidad absoluta porque no solo entretiene, también culturiza y te asoma al infinito universo de los secretos de los libros». Javier Sierra, La Sexta «Una de las mejores definiciones que puedan encontrarse de novela histórica. Zambúllanse [...] en esta gran novela, y disfrútenla. Vale la pena». Agustí Fancelli, El País «El thriller histórico más influyente de la historia de la literatura. [...] El nombre de la rosa no solo habla del pasado, sino también del presente. Eco, con su habitual gusto por los juegos metalingüísticos, se \"introduce\" en la novela como el receptor de la misma, como si hubiera encontrado el manuscrito original del siglo XIV y simplemente lo hubiera traducido». Carlos Joric, La Vanguardia «Eco tuvo el humor de mostrar a sus lectores que los intelectuales pueden verse enredados en las mismas situaciones banales, prosaicas y engorrosas que el resto de los mortales: [...] un ejército de crítica social y rebelión personal». El Diario Montañés - Sotileza «Aquí hay misterios turbadores, personajes vívidos, un retrato logrado de una época fascinante, humor sutil, sucesos inesperados y una prosa ágil que puede adaptarse a los registros de la fe, la duda, el horror, el éxtasis amoroso y la desolación». David Lodge «Eco proporcionó una nueva forma de leer no sólo sus novelas sino también de leer e interpretar la realidad que nos rodea y que nos influye. Ofrecía la posibilidad de buscar nuevos ángulos en los rincones de los textos. Eco invitaba a dejar atrás cualquier prejuicio en la búsqueda de respuestas, que no nos dejásemos llevar por aquello que creemos que sabemos, sino dejarse llevar por la inmensa fuerza del descubrimiento». Martí Gironell, El Mundo «El libro más inteligente, pero también más divertido, de los últimos años». Lars Gustafsson, Der Spiegel', 'http://books.google.com/books/content?id=OndVsK3zb4AC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 653, 'Fiction', '2010-11-12', 'OndVsK3zb4AC', '2026-08-15 18:36:10', ''),
(1666, 23, 'Fahrenheit 451 (Novela gráfica) / Ray Bradbury\'s Fahrenheit 451', 'Ray Bradbury', 'La adaptación gráfica oficial de la novela clásica de Ray Bradbury. Fahrenheit 451 cuenta la historia de un sombrío y horroroso futuro. Montag, el protagonista, pertenece a una extraña brigada de bomberos cuya misión, paradójicamente, no es la de sofocar incendios, sino la de provocarlos para quemar libros. Porque en el país de Montag está terminantemente prohibido leer. Porque leer obliga a pensar, y en el país de Montag está prohibido pensar. Porque leer impide ser ingenuamente feliz, y en el país de Montag hay que ser feliz a la fuerza... Tim Hamilton convierte en imagen la visionaria distopía ideada por Ray Bradbury a mediados del siglo pasado, sin saberlo mas quizá intuyendo la vigencia de una advertencia imperecedera. ENGLISH DESCRIPTION Now an HBO Original Movie starring Michael B. Jordan (Black Panther), Sofia Boutella (Star Trek: Beyond), and Michael Shannon (The Shape of Water).-An Eisner Award Nominee \"Monday burn Millay, Wednesday Whitman, Friday Faulkner, burn \'em to ashes, then burn the ashes.\" For Guy Montag, a career fireman for whom kerosene is perfume, this is not just an official slogan. It is a mantra, a duty, a way of life in a tightly monitored world where thinking is dangerous and books are forbidden. In 1953, Ray Bradbury envisioned one of the world\'s most unforgettable dystopian futures, and in Ray Bradbury\'s Fahrenheit 451, the artist Tim Hamilton translates this frightening modern masterpiece into a gorgeously imagined graphic novel. As could only occur with Bradbury\'s full cooperation in this authorized adaptation, Hamilton has created a striking work of art that uniquely captures Montag\'s awakening to the evil of government-controlled thought and the inestimable value of philosophy, theology, and literature. Including an original foreword by Ray Bradbury and fully depicting the brilliance and force of his canonic and beloved masterwork, Ray Bradbury\'s Fahrenheit 451 is an exceptional, haunting work of graphic literature.', 'http://books.google.com/books/content?id=mm6REAAAQBAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 'Young Adult Fiction', '2019-05-21', 'mm6REAAAQBAJ', '2026-09-02 18:02:21', ''),
